insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('da-mual-jankad-bei-da-koeoedn-wia-da-hustinettnbaea', 'Da Mual jankad bei da Köödn wia da Hustinettnbäa!', '', '', '', 'Wiener Mechaniker-Slang', 'Der Murl jankert bei der Kälte wie der Hustinettenbär!', '[{"kategorie": "wörtlich", "text": "\"Der Motor ruckelt bei der Kälte wie der [[Hustinettenbär]]!\"  2. Bei der Kälte stottert der Motor, als würde er sich selbst anhusten!  3. Bei Kälte läuft der Motor so unrund, als hätte er Bronchitis!"}]'::jsonb, ''),
  ('do-muassd-scho-kolumbiana-sei-dass-da-in-kaas-in-kaukau-eibreckln-tuast', 'Do muassd scho Kolumbiana sei, dass da in Kaas in Kaukau eibreckln tuast!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Da musst du schon Kolumbianer sein, dass du dir den Käse in den Kakao einbröckeln tust!', '[{"kategorie": "wörtlich", "text": "\"Da musst du wirklich Kolumbianer sein, um auf die Idee zu kommen, Käse bröckchenweise in den Kakao zu streuen!\"  2. Nur ein echter Kolumbianer kommt auf die glorreiche Idee, Käse in heiße Schokolade einzutunken!  3. Käse im Kakao? Das geht wohl nur, wenn du Kolumbianer bist!"}]'::jsonb, ''),
  ('do-host-ma-jo-wos-scheens-eibreckld-und-i-muass-den-gaunzn-schaas-jetzt-ausboodn', 'Do host ma jo wos Scheens eibreckld - und I muass den gaunzn Schaas jetzt ausboodn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da hast du mir ja was Schönes eingebröckelt - und ich muss den ganzen Schas jetzt ausbaden!', '[{"kategorie": "wörtlich", "text": "\"Da hast du mir ja was Schönes eingebrockt - und ich muss den ganzen Mist jetzt ausbaden!\"  2. Das hast du ja fein hingekriegt – und ich steh jetzt da mit dem Dreck und muss alles richten!  3. Da hast du mir ja ein schönes Ei gelegt - und ich muss es jetzt ausbrüten!"}]'::jsonb, 'wem wos eibreckln'),
  ('wem-wos-eibreckln', 'wem wos eibreckln', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem etwas einbröckeln', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas einbrocken\""}, {"kategorie": "", "text": "jemandem ein Ei legen"}, {"kategorie": "", "text": "jemandem Ärger einhandeln"}]'::jsonb, ''),
  ('si-eidiisln', 'si eidiisln', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich eindieseln', '[{"kategorie": "wörtlich", "text": "\"sich eindieseln\" (von \"Diesel\"=\"Dieselkraftstoff\", benannt nach Rudolf Diesel [1858–1913], dem Erfinder des Dieselmotors)"}, {"kategorie": "scherzhaft für", "text": "sich betrinken, sich besaufen, sich einen Vollrausch antrinken, \"sich wegschießen\", [[sich]] eintrankeln, [[schwassn]]"}]'::jsonb, ''),
  ('si-an-jedn-toog-eidiisln-is-hoid-aa-ka-richtigs-lebnskonzept', 'Si an jedn Toog eidiisln is hoid aa ka richtigs Lebnskonzept!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sich jeden Tag einzudieseln, ist halt auch kein richtiges Lebenskonzept!', '[{"kategorie": "wörtlich", "text": "\"Sich jeden Tag einen Vollrausch anzutrinken, ist halt auch kein richtiges Lebenskonzept!\"  2. Sich täglich wegzuschießen, ist auf Dauer halt auch keine Lösung!  3. Wenn’s Leben nur mehr aus Spritzer und Vollgas besteht, ist irgendwann Schicht im Schacht!"}]'::jsonb, ''),
  ('heast-des-eialaawal-is-mea-a-eadaepfae-ois-a-kuugl', 'Heast, des Eialaawal is mea a Eadäpfä ois a Kuugl!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Hör mal, dieser Eierball ist mehr ein Erdapfel als ''ne Kugel!', '[{"kategorie": "wrötlich", "text": "\"Hey, dieser Eierball ist mehr ''ne Katoffel als ''ne Kugel!\"  2. Hey, der Ball ist so verbeult, als wär er vom Acker und nicht vom Sportplatz!  3. Was da über den Rasen eiert, ist mehr Kartoffel als Fußball!"}]'::jsonb, ''),
  ('de-amis-haum-von-fuassboi-ka-aunung-sunst-daedns-ned-so-an-braunan-eialaawal-noochjaukn', 'De Amis haum von Fuassboi ka Aunung - sunst dädns ned so an braunan Eialaawal noochjaukn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Amis haben von Fußball keine Ahnung - sonst würden sie nicht so einem braunen Eierlaberl nachjauken!', '[{"kategorie": "wörtlich", "text": "\"Die Amis haben von Fußball keine Ahnung - sonst würden sie nicht so einem braunen Eierball nachjagen!\"  2. Wenn die Amis wüssten, wie echter Fußball geht, würden sie nicht einem braunen Ei über den Rasen hinterherhecheln!  3. Fußball verstehen die Amis nicht – sonst hätten sie das mit dem Leder-Ei längst sein lassen!"}]'::jsonb, ''),
  ('bevuas-ins-bett-geed-draad-sa-si-de-hoa-imma-no-mit-iare-locknwickla-ei-daunn-schauds-aus-wiara-antenn-und-i-hob-kaan-bock-mea', 'Bevuas ins Bett geed, draad sa si de Hoa imma no mit iare Locknwickla ei - daunn schauds aus wiara Antenn, und I hob kaan Bock mea!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Bevor sie ins Bett geht, dreht sie sich die Haare immer noch mit ihren Lockenwicklern ein - dann schaut sie aus wie eine Antenne und ich hab keinen Bock mehr!', '[{"kategorie": "wörtlich", "text": "\"Bevor sie ins Bett geht, dreht sie sich die Haare immer noch mit Lockenwicklern ein - dann sieht sie aus wie eine Antenne und ich hab keine Lust mehr!\"  2. Jeden Abend packt sie sich die Haare in Lockenwickler – danach schaut sie aus wie eine Antenne, und bei mir ist die Stimmung dahin!  3. Sobald sie sich am Abend die Wickler in die Haare steckt, sieht sie aus wie eine Retro-Antenne – da vergeht mir jede Romantik!"}]'::jsonb, ''),
  ('loss-di-von-dem-gauna-nua-ned-eidraan', 'Loss di von dem Gauna nua ned eidraan!', '', '', '', 'Wiener Gaunersprache', 'Lass dich von dem Gauner nur nicht eindrehen!', '[{"kategorie": "wörtlich", "text": "\"Lass dich von dem Gauner nur nicht einwickeln!\"  2. Fall auf den Gauner bloß nicht rein!  3. Glaub dem Typen kein Wort – der wickelt dich schneller ein, als du schauen kannst!"}]'::jsonb, ''),
  ('in-schuali-weama-jetzt-laenga-ned-seeng-den-haums-auf-zeen-joa-eidraad', 'In Schuali weama jetzt länga ned seeng - den haums auf zeen Joa eidraad!', '', '', '', 'Wiener Gaunersprache', 'Den Schurli werden wir jetzt länger nicht sehen - den haben sie auf zehn Jahre eingedreht!', '[{"kategorie": "wörtlich", "text": "\"Den Schurli werden wir jetzt länger nicht mehr sehen - den haben sie auf zehn Jahre eingebuchtet!\"  2. Den Schurli sehen wir jetzt länger nicht – der sitzt für zehn Jahre ein!  3. Der Schurli wird eine Zeitlang nicht auftauchen – er verbüßt eine zehnjährige Haftstrafe!"}]'::jsonb, ''),
  ('du-muassd-des-eikloa-sauwa-vom-eigoeoeb-trennan-sunst-wiad-da-schnaeae-ned-schdeif', 'Du muassd des Eikloa sauwa vom Eigööb trennan - sunst wiad da Schnää ned schdeif!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Du musst das Eiklar sauber vom Eigelb trennen – sonst wird der Schnee nicht steif!', '[{"kategorie": "wörtlich", "text": "\"Du musst das Eiweiß ganz sauber vom Eigelb trennen – sonst wird der Eischnee nicht steif!\"  2. Du musst das Eiklar vollständig vom Eigelb trennen, sonst lässt sich kein stabiler Eischnee schlagen!  3. Trenne das Eiweiß sorgfältig vom Dotter – sonst wird der Schnee nix!"}]'::jsonb, ''),
  ('bei-da-omi-woa-de-eibrenn-pflicht-sogoa-da-schbinood-hod-aane-kriagd', 'Bei da Omi woa de Eibrenn Pflicht - sogoa da Schbinood hod aane kriagd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Bei der Omi war die Einbrenn Pflicht - sogar der Spinat hat eine gekriegt!', '[{"kategorie": "wörtlich", "text": "\"Bei Oma war die Mehlschitze Pflicht - sogar der Spinat bekam eine reingerührt!\"  2. Bei Oma kam die Einbrenn überall rein – nicht einmal der Spinat blieb verschont!  3. Bei meiner Großmutter war die Einbrenn ein Fixpunkt – auch Spinat wurde damit abgerundet!"}]'::jsonb, ''),
  ('de-sunn-hod-ollas-eibrennd-do-wochsd-jetzt-nix-mea', 'De Sunn hod ollas eibrennd - do wochsd jetzt nix mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Sonne hat alles eingebrannt - da wächst jetzt nichts mehr!', '[{"kategorie": "wörtlich", "text": "\"Die Sonne hat sich derart in die Erde eingebrannt, dass dort jetzt kein Halm mehr wächst!\"  2. Die Sonne hat den Boden dermaßen versengt, dass dort jetzt nichts mehr wächst!\"   3. Die Sonne hat sich ins Land gefressen – übrig geblieben ist nur verbrannte Erde!"}]'::jsonb, ''),
  ('eana-woppn-haums-auf-jeds-weifassl-eibrennd', 'Eana Woppn haums auf jeds Weifassl eibrennd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ihr Wappen haben sie auf jedes Weinfass eingebrannt!', '[{"kategorie": "wörtlich", "text": "\"Ihr Familienwappen wurde auf jedes Weinfass eingebrannt!\"  2. Jedes Fass trägt die eingebrannte Kennzeichnung ihres traditionsreichen Familienwappens!  3. Auf jedes Fass haben sie ihr Familienwappen als Herkunftssiegel eingebrannt!"}]'::jsonb, ''),
  ('i-brenn-da-s-schnoeoe-ei-daunn-wiad-s-wiida-essboa', 'I brenn da''s schnöö ei, daunn wiad''s wiida essboa!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich brenn dir schnell was ein - dann wird das wieder essbar!', '[{"kategorie": "wörtlich", "text": "\"Ich rühr die schnell ''ne Einbrenn rein - dann wird das wieder essbar!\"  2. Ich rühr dir schnell ''ne Mehlschwitze rein, dann ist das wieder genießbar!  3. Ein bissl Mehl und Butter, schnell eingerührt – und das Ganze ist gerettet!"}]'::jsonb, ''),
  ('wem-wos-eibrennan', 'wem wos eibrennan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem etwas einbrennen', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas anhängen\""}, {"kategorie": "", "text": "\"jemandem etwas in die Schuhe schieben\";  3.\"jemandem die Schuld für etwas zuschieben"}]'::jsonb, 'Wüüsd des jetzt leichd mia eibrannan? Du bist doch schuid aun dem gaunzn Chaos!'),
  ('wueuesd-des-jetzt-leichd-mia-eibrannan-du-bist-doch-schuid-aun-dem-gaunzn-chaos', 'Wüüsd des jetzt leichd mia eibrannan? Du bist doch schuid aun dem gaunzn Chaos!', '', '', '', 'Wiener Gaunersprache', 'Willst du das jetzt vielleicht mir einbrennen? Du bist doch schuld an dem ganzen Chaos!', '[{"kategorie": "wörtlich", "text": "\"Willst du das jetzt vielleicht mir anhängen? Du bist doch schuld an dem ganzen Chaos!\"  2. Willst du das jetzt etwa mir in die Schuhe schieben? Du hast das ganze Chasos doch verursacht!  3. Willst du mir jetzt ernsthaft die Schuld an dem ganzen Chaos zuschieben? Du weißt doch, dass das auf dein Konto geht!"}]'::jsonb, 'wem wos eibrennan'),
  ('seita-de-neiche-hockn-hod-isa-sauwa-eibrennd-glaubd-ea-is-wos-bessas', 'Seita de neiche Hockn hod, isa sauwa eibrennd - glaubd, ea is wos Bessas!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seit er die neue Hacken hat, is er ganz schön eingebrannt – glaubt, er is was Besseres!', '[{"kategorie": "wörtlich", "text": "\"Seit er die neue Stelle hat, is er ganz schön eingebildet – glaubt, er sei was Besseres!\"  2. Seit seinem Jobwechsel wirkt er ziemlich überheblich - glaubt, er is was Besseres!  3. Früher war er normal – aber jetzt, wo er den neuen Job hat, gibt er sich, als wär er der große Zampano!"}]'::jsonb, ''),
  ('eibrennde-suppn', 'eibrennde Suppn', '', '', '', 'Wiener Küche & Gaumenfreuden', 'eingebrannte Suppe', '[{"kategorie": "wörtlich", "text": "\"Einbrennsuppe\", (Küchenjargon): \"gebrannte Mehlsuppe\" (um das Aroma zu verbessern, wird zuerst das Mehl in der Pfanne goldbraun angeröstet oder aus Mehl und Fett eine blonde bis braune Mehlschwitze hergestellt und dann mit Wasser, teils auch mit Fleisch- oder Geflügelbrühe durchgekocht)"}]'::jsonb, ''),
  ('eibrennde-hund', 'eibrennde Hund', '', '', '', 'Wiener Küche & Gaumenfreuden', 'eingebrannte Hunde', '[{"kategorie": "wörtlich", "text": "\"eingebrannte Erdäpfel\""}, {"kategorie": "Küchenjargon", "text": "\"eingebrannte Kartoffeln\" (um das Aroma zu verbessern, wird zuerst das Mehl in der Pfanne goldbraun angeröstet oder aus Mehl und Fett eine blonde bis braune Mehlschwitze hergestellt und dann mit Wasser, teils auch mit Fleisch- oder Geflügelbrühe durchgekocht)"}]'::jsonb, ''),
  ('tua-ned-so-einedraan', 'Tua ned so einedraan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Tu nicht so reindrehen!', '[{"kategorie": "wörtlich", "text": "\"Gib nicht so an!\"  2. Hör auf zu protzen!  3. Du brauchst nicht so anzugeben!  4. Lass die Aufschneiderei!"}]'::jsonb, ''),
  ('loss-di-ned-einedraan', 'Loss di ned einedraan!', '', '', '', 'Wiener Gaunersprache', 'Lass dich nicht reindrehen!', '[{"kategorie": "wörtlich", "text": "\"Lass dich nicht hinters Licht führen!\"  2. Lass dich nicht anschmieren!  3. Lass dich nicht über den Tisch ziehen!  4. Lass dich in nichts hineinziehen!"}]'::jsonb, ''),
  ('de-wue-se-beim-schaeaef-einedraan', 'De wü se beim Schääf einedraan!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die will sich beim Chef reindrehen!', '[{"kategorie": "wörtlich", "text": "\"Die möchte sich beim Chef einschleimen!\"  2. Die versucht, sich beim Chef einzuschmeicheln!  3. Die möchte sich beim Chef Liebkind machen!"}]'::jsonb, ''),
  ('dea-einedraara-is-scho-wiida-befoeadad-wuan', 'Dea Einedraara is scho wiida beföadad wuan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Reindreher ist schon wieder befördert worden!', '[{"kategorie": "wörtlich", "text": "\"Dieser Schaumschläger ist schon wieder befördert worden!\"  2. Dieser Wichtigtuer hat sich schon wieder nach oben gedient!  3. Und schon wieder ist dieser Blender mit einer Beförderung belohnt worden!  4. Und wieder hat man diesen Angeber befördert!"}]'::jsonb, ''),
  ('sei-letzte-entscheidung-woara-a-klassischa-einedraara', 'Sei letzte Entscheidung woara a klassischa Einedraara!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seine letzte Entscheidung war ein klassischer Reindreher!', '[{"kategorie": "wörtlich", "text": "\"Seine letzte Entscheidung war ein klassischer Selbstfaller!\"  2. Seine letzte Entscheidung war ein Schuss ins eigene Knie!  3. Seine letzte Entscheidung war ein wahrer [[Einfahrer]]!"}]'::jsonb, ''),
  ('sei-einedraararei-is-afoch-nua-krinsch', 'Sei Einedraararei is afoch nua krinsch!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Seine Reindreherei ist einfach nur ''cringe''!', '[{"kategorie": "wörtlich", "text": "\"Sein ständiges Protzgehabe ist einfach nur ''cringe''!\"  2. Seine Selbstbeweihräucherung ist einfach nur zum Fremdschämen!  3. Sein aufgeblasenes Getue ist der Super-GAU der Peinlichkeit!"}]'::jsonb, 'Des is krinsch!'),
  ('des-is-a-klassische-einedraararei-ka-wuat-von-dem-wos-a-soogd-is-woa', 'Des is a klassische Einedraararei - ka Wuat von dem, wos a soogd, is woa!', '', '', '', 'Wiener Gaunersprache', 'Das ist eine klassische Reindreherei - kein Wort von dem, was er sagt, ist wahr!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein klassischer Betrug - kein Wort von dem, was er sagt, ist wahr!\"  2. Was der da verzapft, sind doch alles nur leere Worthülsen – reiner Schwindel, kein Funken Substanz dahinter!  3. Was der da abliefert, ist reine Schaumschlägerei – Irreführung und Täuschung inklusive!"}]'::jsonb, ''),
  ('dea-dillo-is-a-typischa-einefetza-imma-vuan-dabei-owa-nix-dahinta', 'Dea Dillo is a typischa Einefetza - imma vuan dabei, owa nix dahinta!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Dieser Dillo ist ein typischer Reinfetzer - immer vorn dabei, aber nichts dahinter!', '[{"kategorie": "wörtlich", "text": "\"Dieser Armleuchter ist ein totaler Schaumschläger - große Klappe, nix dahinter!\"  2. \"Dieser Vollpfosten ist ein reiner Selbstdarsteller - immer ganz vorne mit dabei, aber nix drauf!\"  3. \"Dieses Schwachkopf ist nichts als ein Blender - schiebt sich immer in den Vordergrund, hat aber rein gar nichts drauf!\""}]'::jsonb, ''),
  ('sei-letzte-entscheidung-woara-a-klassischa-einefetza', 'Sei letzte Entscheidung woara a klassischa Einefetza!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Seine letzte Entscheidung war ein klassischer Reinfetzer!', '[{"kategorie": "wörtlich", "text": "\"Seine letzte Entscheidung war ein klassischer Selbstfaller!\"  2. Seine letzte Entscheidung war ein Schuss ins eigene Knie!  3. Seine letzte Entscheidung war ein wahrer [[Einfahrer]]!"}]'::jsonb, ''),
  ('jetzt-isa-leichd-eigschbritzd-owa-in-zwa-schdund-is-dea-fett-wia-de-russische-eadn', 'Jetzt isa leichd eigschbritzd, owa in zwa Schdund is dea fett wia de russische Eadn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Jetzt ist er leicht eingespritzt, aber in zwei Stunden ist der fett wie die russische Erde!', '[{"kategorie": "wörtlich", "text": "\"Jetzt ist er leicht angeheitert, aber in zwei Stunden ist der fett wie die russische Erde!\"  2. Jetzt hat er einen Schwips, aber in zwei Stunden liegt er unter’m Tisch wie ein nasser Sack!  3. Jetzt hat er erst einen Leichten sitzen, aber in zwei Stunden ist er [[fett]] wie eine Haubitze!"}]'::jsonb, ''),
  ('heast-eigspritzda-host-dei-resthian-in-da-gardaroob-oogeem', 'Heast Eigspritzda, host dei Resthian in da Gardaroob oogeem?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hör mal, Einspritzter, hast du dein Resthirn in der Garderobe abgegeben?', '[{"kategorie": "wörtlich", "text": "\"Hey, du Schwipskopf, hast du dein Resthirn in der Garderobe abgegeben?\"  2. Sag mal, Schwipsnase – ist dein Restverstand im letzten Glas ersoffen?  3. Hey, [[Schwindlicher]], hast du dein Resthirn gegen fünf [[Stamperln]] eingetauscht?"}]'::jsonb, ''),
  ('waunn-dea-ins-wiatshaus-kummd-isa-imma-scho-leichd-augseisld-und-waunna-daunn-haamgeed-muass-eam-sei-oide-von-da-schdrossn-aufklaum', 'Waunn dea ins Wiatshaus kummd, isa imma scho leichd augseisld - und waunna daunn haamgeed, muass eam sei Oide von da Schdrossn aufklaum!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der ins Wirtshaus kommt, ist er schon leicht angesäuselt - und wenn er dann heimgeht, muss ihn seine Alte von der Straße aufklauben!', '[{"kategorie": "wörtlich", "text": "\"Wenn der ins Wirtshaus kommt, hat er schon einen Leichten sitzen - und wenn er dann heimgeht, muss ihn seine Alte von der Straße aufklauben!\"  2. Wenn der auftaucht, hat er schon einen sitzen – und am Schluss trägt ihn seine Frau heim wie einen nassen Teppich!  3. Wenn der an der Schank auftaucht, ist er schon halb blau – und wenn er dann heimgeht, muss ihn seine Alte mit dem Besen einsammeln!"}]'::jsonb, ''),
  ('si-auseisln', 'si auseisln', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich ansäuseln', '[{"kategorie": "wörtlich", "text": "\"sich ansäuseln\" (vom mittelhochdeutschen \"sūsen\"=\"sausen\")"}, {"kategorie": "scherzhaft für", "text": "sich einen Schwips antrinken, sich einen Rausch antrinken, [[sich]] anröhreln, [[sich]] antrankeln, [[si]] autschechan, [[si]] auschwappn, [[si]] auflaschln"}]'::jsonb, 'Wea si jedn Toog auseisld, muass auf sei Resthian vatraun!'),
  ('wea-si-jedn-toog-auseisld-muass-auf-sei-resthian-vatraun', 'Wea si jedn Toog auseisld, muass auf sei Resthian vatraun!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wer sich jeden Tag ansäuselt, muss auf sein Resthirn vertrauen!', '[{"kategorie": "wörtlich", "text": "\"Wer sich jeden Tag einen Schwips antrinkt, muss auf sein Resthirn vertrauen!\"  2. Wer sich täglich wegschwipst, muss auf sein Notstromgehirn vertrauen!  3. Wer sich täglich einen antrinkt, muss hoffen, dass sein Resthirn den Weg zurück kennt!"}]'::jsonb, 'si auseisln'),
  ('ois-augseislda-waundld-ma-glicklicha-duachs-leebm', 'Ois Augseislda waundld ma glicklicha duachs Leebm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Als Angesäuselter wandelt man glücklicher durchs Leben!', '[{"kategorie": "wörtlich", "text": "\"Als Schwipskopf wandelt man glücklicher durchs Leben!\"  2. Mit ’nem Dauerschwips sieht die Welt gleich viel freundlicher aus!  3. Als Rauschiger stolpert man entspannter durchs Dasein!"}]'::jsonb, ''),
  ('i-ziag-easchd-zum-joareswechsl-aus-eenda-ned', 'I ziag easchd zum Joareswechsl aus - eenda ned!"', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich zieh erst zum Jahreswechsel aus - ehender nicht!', '[{"kategorie": "wörtlich", "text": "\"Ich zieh erst zum Jahreswechsel aus - früher nicht!\"  2. Ich bleib noch bis zum Jahreswechsel – zeitiger geht nix!  3. Ich bleibe, bis das Jahr zu Ende ist - eher geh ich nicht!"}]'::jsonb, ''),
  ('dea-haud-uandlich-eine', 'Dea haud uandlich eine!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der haut ordentlich rein!', '[{"kategorie": "wörtlich", "text": "\"Der gibt ordentlich Gas!\"  2. \"Der zieht voll durch!\"  3. Der legt sich richtig ins Zeug!  4. (scherzhaft für): Der haut ganz schön rein beim Essen!  5. Der frisst wie ein [[Scheunendrescher]]!"}]'::jsonb, ''),
  ('wueuest-di-bei-mia-einehaun', 'Wüüst di bei mia einehaun?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Willst dich bei mir reinhauen?', '[{"kategorie": "wörtlich", "text": "\"Willst du dich bei mir einschmeicheln?\"  2. Willst du dich bei mir Liebkind machen?  3. Willst du mir Honig ums Maul schmieren?  3. Willst du dich bei mir einschleimen?"}]'::jsonb, ''),
  ('de-san-einadeifaed-kumman-wia-waunn-draussn-woeoeduntagaung-warad', 'De san einadeifäd kumman, wia waunn draussn Wööduntagaung warad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die sind reingeteufelt gekommen, wie wenn draußen Weltuntergang wäre!', '[{"kategorie": "wörtlich", "text": "Die sind hereingestürmt, als ob draußen gerade Weltuntergang wäre!  2. Die sind hereingestürmt, als würde draußen der Himmel einstürzen!  3. Die kamen hereingerauscht, als wäre der Teufel hinter ihnen her!"}]'::jsonb, ''),
  ('de-kinda-san-draussd-umanaundadeifaed-wia-junge-hund-auf-da-wiisn', 'De Kinda san draussd umanaundadeifäd wia junge Hund auf da Wiisn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Kinder sind draußen umeinandergeteufelt wie junge Hunde auf der Wiese!', '[{"kategorie": "wörtlich", "text": "\"Die Kinder sind draußen herumgetollt wie junge Hunde auf der Wiese!\"  2. Die Kinder haben draußen herumgetobt wie eine Bande junger Welpen!  3. Die Kinder draußen herumgesaust wie junge Fohlen auf einer Frühlingsweide!"}]'::jsonb, ''),
  ('wem-wo-einedeatan', 'wem wo einedeatan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden wo einetheatern!', '[{"kategorie": "wörtlich", "text": "\"jemanden in etwas hineinreiten\""}, {"kategorie": "", "text": "jemanden in eine missliche Lage bringen"}, {"kategorie": "", "text": "jemanden in die Pfanne hauen"}, {"kategorie": "", "text": "jemanden in eine Sache mit hineinziehen"}]'::jsonb, 'Ea hod mi in des Investment einedeatad, und ea wiad dafia biassn!'),
  ('ea-hod-mi-in-des-investment-einedeatad-und-ea-wiad-dafia-biassn', 'Ea hod mi in des Investment einedeatad, und ea wiad dafia biassn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat mich in dieses Investment reintheatert, und er wird dafür büßen!', '[{"kategorie": "wörtlich", "text": "\"Er hat mich in dieses Investment reingeritten, und er wird dafür büßen!\"  2. Er hat mich in dieses Investment mit reingezogen, und das lasse ich ihm nicht einfach so durchgehen!  3. Er hat mich zu dieser Investition verleitet, und er wird sich dafür verantworten müssen!"}]'::jsonb, 'wem wo einedeatan'),
  ('ois-wiina-host-eam-drauf-in-aansaschmaeae', 'Ois Wiina host eam drauf, in Aansaschmää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als Wiener hast du ihn drauf, den Einserschmäh!', '[{"kategorie": "wörtlich", "text": "\"\"Als Wiener hast du Trick 17 natürlich drauf!\"  2. Als Wiener hast du natürlich den Schmäh der Spitzenklasse drauf!  3. Als Wiener kriegst den Einserschmäh schon mit’m Kaffee eingeimpft!"}]'::jsonb, ''),
  ('ois-aansagooli-deafa-nii-und-nimma-a-so-a-eiatiarl-kassian', 'Ois Aansagooli deafa nii und nimma a so a Eiatiarl kassian!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Als Einsergoalie darf er nie und nimmer ein solches Eiertürl kassieren!', '[{"kategorie": "wörtlich", "text": "\"Als Nummer 1 im Kasten darf er nie und nimmer einen solch vermeidbaren Treffer kassieren!\"  2. Als Stammtorhüter darf er sich keinesfalls einen so leicht zu vermeidenden Gegentreffer einfangen!  3. Das war ein Gegentor, das ein Stammkeeper unter keinen Umständen kassieren darf!"}]'::jsonb, ''),
  ('ois-aansagoimau-deafa-nii-und-nimma-a-so-a-eiatiarl-kassian', 'Ois Aansagoimau deafa nii und nimma a so a Eiatiarl kassian!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Als Einsergoalmann darf er nie und nimmer ein solches Eiertürl kassieren!', '[{"kategorie": "wörtlich", "text": "\"Als Nummer 1 im Kasten darf er nie und nimmer einen solch vermeidbaren Treffer kassieren!\"  2. Als Stammtorhüter darf er sich keinesfalls einen so leicht zu vermeidenden Gegentreffer einfangen!  3. Das war ein Gegentor, das ein Stammkeeper unter keinen Umständen kassieren darf!"}]'::jsonb, ''),
  ('de-aansapartii-schdeed-muang-schbueuens-gengan-taboeoenfiara', 'De Aansapartii schdeed - muang schbüüns gengan Taböönfiara!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Einserpartie steht - morgen spielen sie gegen den Tabellenführer!', '[{"kategorie": "wörtlich", "text": "\"Die erste Mannschaft steht - morgen geht''s gegen den Tabellenführer!\"  2. Die Stammelf ist fix – morgen geht''s gegen den Ligaprimus!  3. Unsere beste Elf ist gesetzt – und morgen wartet das Spiel gegen den Tabellenführer!"}]'::jsonb, ''),
  ('waunn-si-de-drei-zsaummtuan-sans-a-echte-aansapartii-de-vaschdengan-si-blind', 'Waunn si de drei zsaummtuan, sans a echte Aansapartii - de vaschdengan si blind!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn sich die drei zusammentun, sind sie eine echte Einserpartie - die verstehen sich blind!', '[{"kategorie": "wörtlich", "text": "\"Wenn sich die drei zusammentun, sind sie ein echtes Dreamtean - die verstehen sich blind!\"  2. Gemeinsam sind die drei ein Spitzenteam - da psst einfach alles!  3. Wenn die drei gemeinsam unterwegs sind, dann sind sie eine eingeschworene Truppe - einfach unschlagbar!"}]'::jsonb, ''),
  ('a-entarische-gegend', 'A entarische Gegend!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Eine entrische Gegend!', '[{"kategorie": "wörtlich", "text": "\"Eine unheimliche Gegend!\"  2. Eine düstere Ecke!  3. Eine abgelegene, fast gespenstische Gegend!"}]'::jsonb, ''),
  ('mia-wiad-gaunz-entarisch-waunn-i-bei-voimond-iwan-oidn-friidhof-gee', 'Mia wiad gaunz entarisch, waunn I bei Voimond iwan oidn Friidhof gee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mir wird ganz entrisch, wenn ich bei Vollmond über den alten Friedhof geh!', '[{"kategorie": "wörtlich", "text": "\"Mir wird ganz unheimlich, wenn ich bei Vollmond über den alten Friedhof geh!\"  2. Ich bekomme ein ganz mulmiges Gefühl, wenn ich bei Vollmond über den alten Friedhof gehe!  3. Es ist mir nicht ganz geheuer, bei Vollmond über den alten Friedhof zu gehen!"}]'::jsonb, ''),
  ('moogst-no-an-eadaepfae', 'Moogst no an Eadäpfä?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Magst du noch einen Erdäpfel?', '[{"kategorie": "wörtlich", "text": "\"Möchtest du noch einen Erdapfel?\"  (im Wienerischen fungiert die Pluralform Erdäpfel heute noch auch als Singular – d.h. Singularform: \"da Eadäpfä\" [\"der Erdäpfel\"] und Pluralform \"de Eadäpfän\" [\"die Erdäpfeln\"])"}, {"kategorie": "", "text": "Willst du noch eine Kartoffel?  3. Hättest du gerne noch eine Kartoffel?"}]'::jsonb, ''),
  ('eadaepfaen-in-da-montua', 'Eadäpfän in da Montua', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Erdäpfel in der Montur', '[{"kategorie": "wörtlich", "text": "\"Kartoffeln in der Montur\""}, {"kategorie": "", "text": "Kartoffeln mit Schale\""}, {"kategorie": "", "text": "Salzkartoffeln mit Schale (\"Kartoffeln mit der Schale gekocht“, also ungeschälte Kartoffeln, meist in Salzwasser gegart)"}]'::jsonb, ''),
  ('heit-gibt-s-eadaepfaen-in-da-montua-dazua-an-kreitatopfn-und-butta', 'Heit gibt''s Eadäpfän in da Montua, dazua an Kreitatopfn und Butta!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Heute gibt es Erdäpfeln in der Montur, dazu Kräutertopfen und Butter', '[{"kategorie": "wörtlich", "text": "\"Heute gibt es Kartoffeln in der Schale, dazu Kräuterquark und Butter!\"  2. Zum Mittagessen gibt es ungeschälte Kartoffeln mit frischem Kräutertopfen und etwas Butter!  3. Heut gibt’s Erdäpfel mit der Haut, dazu Kräutertopfen und Butter!"}]'::jsonb, ''),
  ('a-guads-eadaepfaegulasch-brauchd-zeit-zwiifaen-und-vueue-paprika', 'A guads Eadäpfägulasch brauchd Zeit, Zwiifän und vüü Paprika!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein gutes Erdäpfelgulasch braucht Zeit, Zwiebeln und viel Paprika!', '[{"kategorie": "wörtlich", "text": "\"Ein gutes Kartoffelgulasch braucht Zeit, Zwiebeln und viel Paprika!\"  2. Wer ein schmackhaftes Kartoffelgulasch will, darf bei Zwiebeln, Paprika und Kochzeit nicht sparen!  3. Geduld, Zwiebeln und Paprika – das ist das Geheimnis eines guten Kartoffelgulaschs!"}]'::jsonb, ''),
  ('obsd-eadaepfaenuudln-schupfnuudln-oda-wuuzlnuudln-zu-eana-sogsd-gmaand-san-in-wiin-imma-desoeoebn-goidbraun-ausbockanan-kartoffaenuudln', 'Obsd Eadäpfänuudln, Schupfnuudln oda Wuuzlnuudln zu eana sogsd - gmaand san in Wiin imma desööbn goidbraun ausbockanan Kartoffänuudln!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ob du ''Erdäpfelnudeln'', ''Schupfnudeln'' oder ''Wuzelnudeln'' zu ihnen sagst – gemeint sind in Wien immer dieselben goldbraun ausgebackenen Kartoffelteinudeln!', '[{"kategorie": "wörtlich", "text": "\"Ob man sie Erdäpfelnudeln, Schupfnudeln oder Wutzelnudeln nennt – gemeint sind in Wien immer dieselben goldbraun gebratenen Kartoffelteigröllchen!\"  2. Wie man sie nennt, spielt keine Rolle: Erdäpfelnudeln, Schupfnudeln oder Wutzelnudeln – in Wien sind es immer die herrlich gebratenen Kartoffelteigstückerln!  3. Drei Namen, ein Genuss: Erdäpfelnudeln, Schupfnudeln oder Wutzelnudeln stehen in Wien für das gleiche knusprige Kartoffelgericht!"}]'::jsonb, ''),
  ('fleischlaawaln-mit-an-eadaepfaepiree-san-a-echta-klassika-unsara-wiina-wiatshauskuchl', 'Fleischlaawaln mit an Eadäpfäpiree san a echta Klassika unsara Wiina Wiatshauskuchl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Fleischlaibchen mit Erdäpfelpüree sind ein echter Klassiker unserer Wiener Wirtshausküche!', '[{"kategorie": "wörtlich", "text": "\"Hackfleischlaibchen mit Kartoffelpüree sind ein echter Klassiker unserer Wiener Wirtshausküche!\"  2. Faschierte Laibchen mit Kartoffelpüree sind ein echter Klassiker der Wiener Hausmannskost!\"  3. (Deutschland): \"Frikadellen mit Kartoffelpüree – ein echter Evergreen der Wiener Wirtshausküche!\""}]'::jsonb, ''),
  ('faschiade-laawaln-mit-an-eadaepfaepiree-san-a-echta-klassika-unsara-wiina-wiatshauskuchl', 'Faschiade Laawaln mit an Eadäpfäpiree san a echta Klassika unsara Wiina Wiatshauskuchl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Faschierte Laibchen mit Erdäpfelpüree sind ein echter Klassiker unserer Wiener Wirtshausküche!', '[{"kategorie": "wörtlich", "text": "\"Hackfleischlaibchen mit Kartoffelpüree sind ein echter Klassiker der Wiener Wirtshausküche!\"  2. Fleischlaibchen mit Kartoffelpüree sind ein echter Klassiker der Wiener Hausmannskost!\"  3. (Deutschland): \"Frikadellen mit Kartoffelpüree – ein echter Evergreen der Wiener Wirtshausküche!\""}]'::jsonb, 'faschiade Laawaln'),
  ('zum-schnitzl-passd-aum-bestn-a-hausgmochda-wiina-eadaepfaesolood', 'Zum Schnitzl passd aum bestn a hausgmochda Wiina Eadäpfäsolood!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zum Schnitzel passt am besten ein hausgemachter Wiener Erdäpfelsalat!', '[{"kategorie": "wörtlich", "text": "\"Zum Schnitzel passt am besten ein hausgemachter Wiener Kartoffelsalat!\"  2. Zum goldgelb ausgebackenen Schnitzel gehört ein echter Wiener Erdäpfelsalat – am besten hausgemacht!  3. Hausgemachter Erdäpfelsalat – die perfekte Beilage zum Wiener Schnitzel!"}]'::jsonb, ''),
  ('im-eadaepfaekoella-liing-no-imma-de-eadaepfaen-vom-letztn-heabst', 'Im Eadäpfäkölla liing no imma de Eadäpfän vom letztn Heabst!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Erdäpfelkeller liegen noch immer die Erdäpfeln vom letzten Herbst!', '[{"kategorie": "wörtlich", "text": "\"Im Kartoffelkeller liegen noch immer die Erdäpfeln vom letzten Herbst!\"  2. Im Erdäpfelkeller lagern noch immer die Knollen vom Vorjahr!  3. Im alten Speisekeller liegen noch die Erdäpfel vom letzten Herbst!"}]'::jsonb, ''),
  ('bevua-dea-ums-eck-kummd-siichsd-vuahea-scho-sein-eadaepfaekoella', 'Bevua dea ums Eck kummd, siichsd vuahea scho sein Eadäpfäkölla!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bevor der ums Eck kommt, siehst du vorher schon seinen Erdäpfelkeller!', '[{"kategorie": "wörtlich", "text": "\"Wenn der ums Eck biegt, siehst du zuerst seinen aufgedunsenen Wanst und dann erst ihn!\"  2. Wenn der um die Kurve kommet, rollt zuerst sein Bauch ums Eck, und dann erst folgt er selbst gemütlich nach!  3. Seine Riesenwampe kurvt vor ihm ums Eck, erst dann kommt er!"}]'::jsonb, ''),
  ('heast-du-gscheada-eadaepfaeschaeaedl-grueuen-is', 'Heast, du gscheada Eadäpfäschäädl - grüün is!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hey, du gescherter Erdäpfelschädel - es ist grün!', '[{"kategorie": "wörtlich", "text": "\"Verdammt, du gescherter Kartoffelkopf, die Ampel zeigt grün!\"  2. \"Du gescherter Bauerntrottel - siehst du nicht, dass es grün ist?\"  3. \"Du depperter [[Neandertaler]] - kriegst du irgendwann mit, dass es grün ist?\""}]'::jsonb, ''),
  ('froog-in-eadaepfaeschaeaedl-aus-st-poeoetn-dea-kennd-jede-obkueazung-duachs-foeoed', 'Froog in Eadäpfäschäädl aus St. Pöötn - dea kennd jede Obküazung duachs Fööd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Frag den Erdäpfelschädel aus Sankt Pölten - der kennt jede Abkürzung durchs Feld!', '[{"kategorie": "wörtlich", "text": "\"Frag den Kartoffelkopf aus Sankt Pölten - der kennt jede Abkürzung durchs Feld!\"  2. Frag den Hirnschüssler aus Sankt Pölten - der kennt jeden Schleichweg durch die Kartoffeläcker!  3. Wenn einer weiß, wo’s durchs Feld geht, dann der Erdäpfelschädel aus Sankt Pölten!"}]'::jsonb, ''),
  ('epa-host-recht-oda-epa-aa-ned', 'Epa host recht, oda epa aa ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Eppa hast du recht, oder eppa auch nicht!', '[{"kategorie": "wörtlich", "text": "\"Vielleicht hast du recht, oder veilleicht auch nicht!\"  2. Möglicherweise hast du recht – oder eben auch nicht!  3. Kann sein, dass du recht hast. Kann aber auch sein, dass du daneben liegst!"}]'::jsonb, ''),
  ('de-waund-is-in-eabsnschbeibgrean-gschdrichn-des-nennd-ma-woi-vintetsch', 'De Waund is in eabsnschbeibgrean gschdrichn - des nennd ma woi Vintetsch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Wand ist in erbsenspeibgrün gestrichen - das nennt man wohl Vintage!', '[{"kategorie": "wörtlich", "text": "\"Die Wand ist in erbsenspeigrüner Farbe gestrichen - das nennt man wohl Vintage!\"  2. Die Wand ist giftgrün gestrichen – Retro mit Brechreizgarantie!  3. Die Wand leuchtet in Kotzgrün – laut Katalog ist das \"natur-inspiriert\"!"}]'::jsonb, ''),
  ('in-peitschalbuam-haums-wiida-moi-in-eabsien-eigliifad', 'In Peitschalbuam haums wiida moi in Eabsien eigliifad!', '', '', '', 'Wiener Gaunersprache', 'Den Peitscherlbuben haben sie wieder mal nach Erbsien gebracht!', '[{"kategorie": "wörtlich", "text": "\"Den Zuhälterjungen haben sie wieder mal im Erbsentempel eingelocht!\"  2. Diesen Strizzi haben sie wieder mal im Erbsenbunker weggesperrt!  3. Der Zälterfuzzi sitzt wieder mal in Erbsien hinter Gittern - mit Eintopf-Vollpension!"}]'::jsonb, ''),
  ('dea-bua-is-so-gschmeidich-dea-eschapiad-sogoa-aus-schdaa', 'Dea Bua is so gschmeidich, dea eschapiad sogoa aus Schdaa!', '', '', '', 'Wiener Gaunersprache', 'Der Bub is so geschmeidig, der echappiert sogar aus Stein!', '[{"kategorie": "wörtlich", "text": "\"Der Bub is so geschmeidig, der echappiert sogar aus der Justizvollzugsanstalt Stein an der Donau!\"  2. Der Kerl ist so flink und beweglich - der entwischt sogar aus dem Hochsicherheitsgefängnis!  3. Der Typ ist so biegsam - der schlüpft sogar aus''m Hääfn in [[Stein]] wie ein Aal aus’m Kübel!"}]'::jsonb, ''),
  ('etla-schaunsn-haums-ghobt-und-ka-aanzige-gnutzd', 'Etla Schaunsn haums ghobt - und ka aanzige gnutzd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Etla Chancen haben sie gehabt - und keine einzige genutzt!', '[{"kategorie": "wörtlich", "text": "\"Sie hatten etliche Chancen, aber sie nutzten keine einzige!\"  2. So viele Chancen hatten sie – und nicht eine davon haben sie genutzt!  3. Sie standen mehrfach vor dem leeren Tor - doch sie machten nichts draus!"}]'::jsonb, ''),
  ('zum-obschiid-gib-i-ia-imma-a-eskimobussal-do-gfreid-sa-si-und-nimmd-mi-daunn-doch-mit-haam', 'Zum Obschiid gib I ia imma a Eskimobussal - do gfreid sa si und nimmd mi daunn doch mit haam!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zum Abschied geb'' ich ihr immer ein Eskimobusserl - da freut sie sich und nimmt mich dann doch mit heim!', '[{"kategorie": "wörtlich", "text": "\"Zum Abschied geb'' ich ihr immer ein Nasenstupserküsschen - da freut sie sich und nimmt mich dann doch mit heim!\"  2. Ein kleines Eskimobusserl zum Schluss, und zack – ich darf mit nach Hause zu ihr!  3. Ich geb ihr zum Abschied ein süßes Stupsbusserl – sie liebt’s und nimmt mich dann doch mit heim!"}]'::jsonb, ''),
  ('ma-hod-de-scherarei-und-de-aungst-extra', 'Ma hod de Scherarei - und de Aungst extra!', '', '', '', 'Wiener Gaunersprache', 'Man hat die Schererei - und die Angst extra!', '[{"kategorie": "wörtlich", "text": "\"Man hat den Ärger - und dazu auch noch Angst!\"  2. Die Probleme kriegt man gratis – und die Angst gibt’s obendrauf!  3. Erst der Ärger, und als Draufgabe dann auch noch die Angst!"}]'::jsonb, ''),
  ('auf-amoi-wueue-mei-oide-a-extrigs-schlofzimma-und-des-noch-zwanzg-joa-in-aan-bett', 'Auf amoi wüü mei Oide a extrigs Schlofzimma - und des noch zwanzg Joa in aan Bett!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Auf einmal will meine Alte ein extriges Schlafzimmer - und das nach zwanzig Jahren im selben Bett!', '[{"kategorie": "wörtlich", "text": "\"Auf einmal will meine Alte ein eigenes Schlafzimmer - und das nach zwanzig Jahren Zweisamkeit im selben Bett!\"  2. Plötzlich braucht meine Alte ihr eigenes Schlafzimmer – und das nach zwanzig Jahren Körperkontakt im selben Bett!  3. Auf einmal braucht meine bessere Hälfte ein getrenntes Schlafzimmer nur für sich - und das nach zwanzig Jahren zusammen kuscheln!"}]'::jsonb, ''),
  ('si-wueue-kaan-08-15-mau-si-suachd-wos-extrigs', 'Si wüü kaan 08/15-Mau - si suachd wos Extrigs!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie will keinen 08/15-Mann - sie sucht was Extriges!', '[{"kategorie": "wörtlich", "text": "\"Sie will keinen 08/15-Mann - sie sucht was ganz Besonderes!\"  2. Sie will keinen 08/15-Typ – sie sucht jemanden mit dem gewissen Etwas!  3. Ein Mann von der Stange reicht ihr nicht – sie will etwas Außergewöhnliches!"}]'::jsonb, ''),
  ('d-ead-is-da-dritte-planet-in-unsan-sonnansystem', 'D''Ead is da dritte Planet in unsan Sonnansystem!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Erde ist der dritte Planet in unserem Sonnensystem!', '[{"kategorie": "wörtlich", "text": "\"Die Erde ist der dritte Planet unseres Sonnensystems!\"  2. Von der Sonne aus gesehen ist die Erde der dritte Planet!  3. Die Erde ist nach Merkur und Venus der dritte Planet in unserem Sonnensystem!"}]'::jsonb, ''),
  ('vua-lauta-zuan-hodas-hendy-aufdread-ghaud', 'Vua lauta Zuan hodas Hendy aufdread ghaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Vor lauter Zorn hat er das Handy auf d''r''Erd gehaut!', '[{"kategorie": "wörtlich", "text": "\"Vor lauter Zorn hat er das Handy auf den Boden geschmissen!\"  2. Im Zorn hat er das Handy zu Boden geworfen!  3. Vor lauter Wut pfefferte er das Handy auf den Boden!"}]'::jsonb, ''),
  ('aufdread-haun', 'aufdread haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf d''r''Ead haun', '[{"kategorie": "wörtlich", "text": "\"auf die Erde hauen\""}, {"kategorie": "", "text": "zu Boden werfen"}, {"kategorie": "", "text": "auf den Boden schmeißen"}]'::jsonb, 'Vua lauta Zuan hodas Hendy aufdread ghaud!'),
  ('indread-gee', 'indread gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'in d''r''Ead gehen', '[{"kategorie": "wörtlich", "text": "\"in die Erde gehen\""}, {"kategorie": "fig.", "text": "schiefgehen, misslingen, fehlschlagen, danebengehen,  in die Hose gehen, in die Binsen gehen"}]'::jsonb, 'De gaunze Planung is indread gaungan - nix hod funktioniad!'),
  ('de-gaunze-planung-is-indread-gaungan-nix-hod-funktioniad', 'De gaunze Planung is indread gaungan - nix hod funktioniad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die ganze Planung ist in d''r''Erd gegangen - nichts hat funktioniert!', '[{"kategorie": "wörtlich", "text": "\"Die ganze Planung ist schiefgegangen – nichts hat funktioniert\"  2. Die gesamte Planung ist danebengegangen – es hat gar nichts geklappt!  3. Die Planung ist total in die Hose gegangen – nichts lief wie es sollte!"}]'::jsonb, 'indread gee'),
  ('si-aufdread-haun', 'si aufdread haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich auf d''r''Erd hauen', '[{"kategorie": "wörtlich", "text": "\"sich auf die Erde hauen\""}, {"kategorie": "", "text": "sich zu Boden werfen"}, {"kategorie": "", "text": "sich auf den Boden schmeißen"}]'::jsonb, 'I hau mi aufdread!'),
  ('i-hau-mi-aufdread', 'I hau mi aufdread!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich haue mich auf d''r''Erd!', '[{"kategorie": "wörtlich", "text": "\"Ich haue mich auf die Erde!\"  2. (fig., Ausruf der Überraschung/des Erstaunens): \"Das haut mich vom Hocker!\"  2. Das haut mich von den Socken!  3. Das haut mich vom [[Stockerl]]!"}]'::jsonb, 'si aufdread haun'),
  ('i-schdee-auf-essigwuaschd-saua-fettig-guad', 'I schdee auf Essigwuaschd - saua, fettig, guad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich steh auf Essigwurst – sauer, fettig, gut!', '[{"kategorie": "wörtlich", "text": "\"Essigwurst ist genau mein Ding – sauer, fettig, gut!\"  2. Ich liebe Essigwurst – schön säuerlich, fett und deftig!  3. Ich bin ein echter Fan von Essigwurst – herzhaft, würzig, ein Genuss!"}]'::jsonb, ''),
  ('da-expedit-von-jeda-boeschdoeoewoa-eafoigd-imma-no-aum-soeoebn-toog', 'Da Expedit von jeda Böschdööwoa eafoigd imma no aum sööbn Toog!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Expedit jeder Bestellware erfolgt immer noch am selben Tag!', '[{"kategorie": "wörtlich", "text": "\"Der Versand sämtlicher Bestellware erfolgt weiterhin taggleich!\"  2. Alle Bestellungen werden noch am selben Tag ausgeliefert!  3. Die Zustellung der Bestellware erfolgt nach wie vor am Tag der Bestellung!"}]'::jsonb, ''),
  ('fias-vapockn-und-vasendn-da-woa-is-da-expedit-zuaschdaendig', 'Fias Vapockn und Vasendn da Woa is da Expedit zuaschdändig!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Fürs Verpacken und Versenden der Ware ist der Expedit zuständig!', '[{"kategorie": "wörtlich", "text": "\"Für Versand und Verpackung der Waren ist die Versandabteilung zuständig!\"  2. Das Verpacken und der Versand der Ware erfolgen durch den Expedit!\"  3. Die Logistikabteilung kümmert sich um Verpackung und Auslieferung!"}]'::jsonb, ''),
  ('bei-mia-gibds-kaane-extrawiaschdln', 'Bei mia gibds kaane Extrawiaschdln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei mir gibt''s keine Extrawürschteln!', '[{"kategorie": "wörtlich", "text": "\"Bei mir gibt''s keine Extrawürste!\"  2. Bei mir gibt''s keine Sonderwünsche!\"  3. Bei mir gibt''s keine Ausnahmen!  4. Sonderbehandlungen gibt’s bei mir nicht!  5. Bei mir gilt für alle das Gleiche!"}]'::jsonb, ''),
  ('kaane-extrawiaschdln', 'Kaane Extrawiaschdln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Keine Extrawürschteln', '[{"kategorie": "wörtlich", "text": "\"Keine Extrawürste!\"  2. Keine Ausnahmen!  3. Keinerlei Sonderwünsche!"}]'::jsonb, ''),
  ('du-mit-deine-extrawiaschdln', 'Du mit deine Extrawiaschdln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Du mit deinen Extrawürschteln!', '[{"kategorie": "wörtlich", "text": "\"Du mit deinen Extrawürsten!\"  2. Du mit deinen Sonderwünschen!  3. Schon wieder Extrawünsche, was?  4. Typisch du – immer musst du was extra wollen!"}]'::jsonb, ''),
  ('desweeng-wea-i-ka-extrawuaschd-broodn', 'Desweeng wea I ka Extrawuaschd broodn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deswegen werde ich keine Extrawurst braten', '[{"kategorie": "wörtlich", "text": "\"Deswegen werde ich keine Ausnahme machen!\"  2. Deswegen allein mache ich keine Extraregel auf!  3. Nur deswegen werde ich keine Sonderbehandlung gewähren!"}]'::jsonb, ''),
  ('extrawuaschd-in-essig-und-oeoe', 'Extrawuaschd in Essig und Öö', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Extrawurst in Essig und Öl', '[{"kategorie": "wörtlich", "text": "\"saure Wurst in Essig und Öl\" (in Scheiben geschnittene [[Extrawurst]], mariniert mit Essig, Öl, Zwiebeln und Gewürzen – ein typisches, deftiges Heurigen-Gericht)"}, {"kategorie": "", "text": "\"Fleischwurst in Essig und Öl\""}, {"kategorie": "", "text": "saure Brühwurst in Essig und Öl"}]'::jsonb, ''),
  ('i-hob-eam-ezzes-geem', 'I hob eam Ezzes geem!', '', '', '', 'Wiener Gaunersprache', 'Ich habe ihm Ezzes gegeben!', '[{"kategorie": "wörtlich", "text": "\"Ich habe ihm Insidertipps gegeben!\"  2. Ich hab ihm ein paar geheime Informationen gesteckt!  3. Ich hab ihm ein paar wertvolle Tricks verraten, die nicht jeder kennt"}]'::jsonb, ''),
  ('mit-ezzes-bin-i-scho-vasuagd-deine-deppadn-tipps-brauch-i-ned', 'Mit Ezzes bin I scho vasuagd - deine deppadn Tipps brauch I ned!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Mit Ezzes bin ich schon versorgt - deine depperten Tipps brauch ich nicht!', '[{"kategorie": "wörtlich", "text": "\"Mit wertvollen Insidertipps bin ich schon versorgt - deine klugen Ratschläge kannst dir stecken!\"  2. Spar dir deine schlauen Sprüche – Ezzes hab ich schon genug!\"  3. Ich bin mit klugen Ratschlägen schon mehr als eingedeckt - noch mehr schlaue Kommentare ertrag ich heut nicht!"}]'::jsonb, ''),
  ('sei-ezzesgeeba-hod-eam-wiida-gschdeckd-wo-wos-zum-hoin-is', 'Sei Ezzesgeeba hod eam wiida gschdeckd, wo wos zum Hoin is!', '', '', '', 'Wiener Gaunersprache', 'Sein Ezzesgeber hat ihm wieder gesteckt, wo was zu holen ist!', '[{"kategorie": "wörtlich", "text": "\"Sein Hinweisgeber hat ihm wieder gesteckt, wo was zu holen ist!\"  2. Sein Tippgeber hat ihm wieder verraten, wo was abzugreifen ist!  3. Sein Informant hat ihm wieder geflüstert, wo''s was abzustauben gibt!"}]'::jsonb, ''),
  ('damit-nix-rutscht-und-den-gschroppen-im-winta-ned-koid-is-hod-ma-eana-friara-de-untagattn-glei-ins-hemad-eignaad', 'Damit nix rutscht und den Gschroppen im Winta ned koid is, hod ma eana friara de Untagattn glei ins Hemad eignaad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Damit nichts rutscht und den Gschroppen im Winter nicht kalt ist, hat man ihnen früher die Untergatten gleich ins Hemd eingenäht!', '[{"kategorie": "wörtlich", "text": "\"Damit nichts rutscht und den Kindern im Winter nicht kalt ist, hat man ihnen früher die Unterhose gleich ins Hemd eingenäht!\"  2. Früher hat man den Kindern das Hemd gleich an die Unterhose drangenäht – so ist nichts verrutscht und im Winter war ihnen nicht mehr so kalt!  3. Damit nix verrutscht und die Kleinen nicht frieren, hat man ihnen früher Hose und Hemd einfach zu einem Einteiler zusammengenäht!"}]'::jsonb, ''),
  ('unsan-paunzaknacka-hod-de-kiiwarei-gestan-eignaad-direkt-von-da-kistn-weg', 'Unsan Paunzaknacka hod de Kiiwarei gestan eignaad - direkt von da Kistn weg!', '', '', '', 'Wiener Gaunersprache', 'Unseren Panzerknacker hat die Kiberei gestern eingenäht - direkt vom Tresor weg!', '[{"kategorie": "wörtlich", "text": "\"Unseren Panzerknacker hat die Kriminalpolizei gestern in den Knast gesperrt - direkt vom Tresor weg!\"  2. Unser Kistenöffner wurde gestern von den Bullen beim Tresorknacken erwischt - und von dort direkt in den Bau gebracht!  3. Die Kripo hat sich gestern unseren besten Panzerknacker geschnappt und direkt vom Tresor weg hinter Gitter gebracht!"}]'::jsonb, ''),
  ('si-wos-einaan', 'si wos einaan', '', '', '', 'Grundwortschatz Wienerisch', 'sich etwas einnähen', '[{"kategorie": "wörtlich", "text": "\"sich etwas in die Wäsche einnähen\" (vom mittelhochdeutschen \"īn næjen\"=\"einnähen\")"}, {"kategorie": "scherzhaft für", "text": "\"sich etwas einverleiben\", \"sich etwas unter den Nagel reißen\", \"etwas an sich bringen\", \"mitgehen lassen\", \"in die eigene Tasche wandern lassen\", klauen, entwenden, [[schnipfen]], [[fladern]], [[flauchen]]"}]'::jsonb, 'Ollas, wos aundare liinglossn, naad si dea Gauna glei ei!'),
  ('ollas-wos-aundare-liinglossn-naad-si-dea-gauna-glei-ei', 'Ollas, wos aundare liinglossn, naad si dea Gauna glei ei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alles, was andere liegenlassen, näht sich der Gauner gleich ein!', '[{"kategorie": "wörtlich", "text": "\"Alles, was andere liegenlassen, lässt der Gauner gleich mitgehen!\"  2. Der Gauner greift sich alles, was nicht niet- und nagelfest ist!  3. Was andere liegen lassen, wandert bei ihm direkt in die eigene Tasche!"}]'::jsonb, 'si wos einaan'),
  ('si-eioeoen', 'si eiöön', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'sich einölen', '[{"kategorie": "wörtlich", "text": "\"sich einölen\" (vom schwedischen \"öl\"=\"Bier\")"}, {"kategorie": "scherzhaft für", "text": "sich betrinken, sich einen Rausch antrinken, sich besaufen, \"sich zugießen\", [[si]] eitrangln, [[schwassn]]"}]'::jsonb, 'Aum Wochnend ööl I mi ei - und zwoa bis Owakantn Untalippn!'),
  ('aum-wochnend-oeoel-i-mi-ei-und-zwoa-bis-owakantn-untalippn', 'Aum Wochnend ööl I mi ei - und zwoa bis Owakantn Untalippn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Am Wochenende öl ich mich ein - und zwar bis Oberkante Unterlippe!', '[{"kategorie": "wörtlich", "text": "\"Am Wochenende gieß ich mich zu - und zwar bis Oberkante Unterlippe!\"  2. Am Wochenende sauf ich mich dicht – bis mir das Bier aus den Ohren läuft!  3. Am Wochenende wird der Kessel geflutet – bis zur Reißlinie!"}]'::jsonb, 'si eiöön'),
  ('mei-oide-tuad-ollas-eipanian-wos-ia-zwischn-de-finga-kummd-fleisch-fisch-gemuese-und-sogoa-in-hund-waunna-ned-aufpassd', 'Mei Oide tuad ollas eipanian, wos ia zwischn de Finga kummd - Fleisch, Fisch, Gemüse und sogoa in Hund, waunna ned aufpassd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Meine Alte tut alles einpanieren, was ihr zwischen die Finger kommt - Fleisch, Fisch, Gemüse und sogar den Hund, wenn er nicht aufpasst!', '[{"kategorie": "wörtlich", "text": "\"Meine Alte umhüllt alles mit einer Panade, was ihr zwischen die Finger kommt - Fleisch, Fisch, Gemüse und sogar den Hund, wenn er nicht aufpasst!\"  2. Meine Frau paniert bei uns alles, was nicht bei drei vom Teller springt – sogar den Hund, wenn er nicht aufpasst!  3. Bei uns kommt alles in die Panier – Fleisch, Fisch, Gemüse und sogar den Hund, wenn er nicht aufpasst!"}]'::jsonb, ''),
  ('den-hob-i-ma-eipaniad', 'Den hob I ma eipaniad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Den habe ich mir einpaniert', '[{"kategorie": "wörtlich", "text": "\"Den habe ich mir mit ein paar netten Worten weichgekocht!\"  2. \"Den habe ich mir ganz sanft eingewickelt!\"  3. \"Den hab ich mir zurechtgeschwatzt!\""}]'::jsonb, ''),
  ('loss-di-eipanian', 'Loss di eipanian!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Lass dich einpanieren!', '[{"kategorie": "wörtlich", "text": "\"Lass dich in Panade einwickeln!\"  2. (scherzhaft für): \"Hau ab! \" 3. Verschwinde!  4. [[Schleich]] dich!   5. Rutsch mir doch den Buckel runter!  6. [[Gee]] päule!  7. [[Moch]] a Woikn!  8. [[Hau]] di iwad Heisa!  9. [[Loss]] di eimagarian!  10. [[Loss]] di eirexn!"}]'::jsonb, ''),
  ('den-fredl-hod-de-haeae-eignaad', 'Den Fredl hod de Hää eignaad!', '', '', '', 'Wiener Gaunersprache', 'Den Fredl hat die Höh eingenäht', '[{"kategorie": "wörtlich", "text": "\"Den Alfred hat die Polizei in den Knast gesperrt!\"  2. Alfred wurde von der Polizei festgenommen und eingebuchtet!  3. Den Fredl haben sie eingebucht – auf frischer Tat ertappt!"}]'::jsonb, ''),
  ('dea-hod-se-des-gaunze-eabe-allaa-eignaad', 'Dea hod se des gaunze Eabe allaa eignaad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat sich das ganze Erbe allein eingenäht!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich das gesamte Erbe allein unter den Nagel gerissen!\"  2. Der hat das komplette Erbe allein eingesackt!  3. Der hat das gesamte Erbe in die eigene Tasche wandern lassen!"}]'::jsonb, ''),
  ('wuevueue-goeoed-soi-i-no-in-de-fiama-einebuttan', 'Wüvüü Gööd soi I no in de Fiama einebuttan?', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wie viel Geld soll ich noch in die Firma reinbuttern?', '[{"kategorie": "wörtlich", "text": "\"Wie viel Geld soll ich noch in die Firma reinschießen?\"  2. Wie viel Kapital soll ich noch in die Firma einbringen?  3. Wie viel Geld soll ich denn noch in die Firma reinpumpen, bevor sich da mal was bewegt?"}]'::jsonb, ''),
  ('de-oide-woa-da-greesste-eifoara-in-mein-leebm', 'De Oide woa da greesste Eifoara in mein Leebm!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Alte war der größte Einfahrer in meinem Leben!', '[{"kategorie": "wörtlich", "text": "\"Die Alte war der größte Reinfall meines Lebens!\"  2. Die Alte war die größte Pleite, die ich je erlebt hab!  3. Diese Frau war die größte Blamage, die ich mir je geleistet habe!"}]'::jsonb, ''),
  ('schiach-eifoan', 'schiach eifoan', '', '', '', 'Wiener Sprüche, die sitzen!', 'schirch einfahren', '[{"kategorie": "wörtlich", "text": "\"sich böse blamieren\""}, {"kategorie": "", "text": "\"voll baden gehen\", böse auf der Schnauze landen"}, {"kategorie": "", "text": "sich ganz tief ins Fettnäpfchen setzen, sich bis auf die Knochen blamieren"}, {"kategorie": "", "text": "eine schlimme Pleite hinlegen"}, {"kategorie": "", "text": "bitter draufzahlen"}]'::jsonb, ''),
  ('sauschiach-eifoan', 'sauschiach eifoan', '', '', '', 'Wiener Sprüche, die sitzen!', 'sauschirch einfahren', '[{"kategorie": "wörtlich", "text": "\"sich böse blamieren\""}, {"kategorie": "", "text": "\"voll baden gehen\", böse auf der Schnauze landen"}, {"kategorie": "", "text": "sich ganz tief ins Fettnäpfchen setzen, sich bis auf die Knochen blamieren"}, {"kategorie": "", "text": "eine ganz schlimme Pleite hinlegen"}, {"kategorie": "", "text": "bitter draufzahlen"}]'::jsonb, ''),
  ('so-sauschiach-bin-i-no-nii-eigfoan', 'So sauschiach bin I no nii eigfoan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So sauschirch bin ich noch nie eingefahren!', '[{"kategorie": "wörtlich", "text": "\"So böse habe ich mich noch nie blamiert!\"  2. Ich bin noch nie so hart auf die Schnauze gefallen!  3. Ich habe noch nie eine derart schlimme Pleite hingelegt!  4. So tief habe ich mich noch nie ins Fettnäpfchen gesetzt!"}]'::jsonb, ''),
  ('glaub-ma-bei-dera-foischn-sau-foast-nua-ei', 'Glaub ma, bei dera foischn Sau foast nua ei!', '', '', '', 'Wiener Gaunersprache', 'Glaub mir, bei dieser falschen Sau fährst du nur ein!', '[{"kategorie": "wörtlich", "text": "Glaub mir, bei dieser falschen Sau landest du auf der Schnauze!  2. Glaub mir, bei dieser falschen Schlange gehst du baden!  3. Glaub mir, bei der falschen Ziege kannst du nur verlieren!"}]'::jsonb, ''),
  ('wem-eifoan-lossn', 'wem eifoan lossn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden einfahren lassen', '[{"kategorie": "wörtlich", "text": "\"jemanden ins Fettnäpfchen treten lassen\""}, {"kategorie": "", "text": "jemanden ins offene Messer laufen lassen"}, {"kategorie": "", "text": "jemanden in die Pfanne hauen"}, {"kategorie": "", "text": "jemanden vorführen, in etwas hineinreiten"}]'::jsonb, 'Kana hod mi jemois so eifoan lossn!'),
  ('kana-hod-mi-jemois-so-eifoan-lossn', 'Kana hod mi jemois so eifoan lossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Keiner hat mich jemals so einfahren lassen!', '[{"kategorie": "wörtlich", "text": "\"Keiner hat mich je so vorgeführt!\"  2. So reingeritten hat mich noch nie jemand!  3. Noch nie hat mich jemand derart ins Messer laufen lassen!"}]'::jsonb, 'wem eifoan lossn'),
  ('waunn-i-ois-kind-a-hochs-fiaba-ghobt-hob-hod-ma-de-omi-imma-koide-essigbaatschaln-gmochd', 'Waunn I ois Kind a hochs Fiaba ghobt hob, hod ma de Omi imma koide Essigbaatschaln gmochd!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Wenn ich als Kind hohes Fieber gehabt hab'', hat mir die Omi immer kalte Essigpatscherln gemacht!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich als Kind hohes Fieber hatte, machte mir die Großmama immer kühle Essigpatscherln!\"  2. Hatte ich als Kind hohes Fieber, legte mir die Großmutter stets kalte Essigwickel auf die Waden!  3. Wenn ich geglüht hab wie ein Ofen, hat mir die Oma immer ihre bewährten Essigpatscherln gemacht!"}]'::jsonb, ''),
  ('bevuas-di-rasiasd-soitasda-s-gsicht-guad-eisaafn', 'Bevuas di rasiasd, soitasda s''Gsicht guad eisaafn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bevor du sich rasierst, solltest du dir das Gesicht gut einseifen!', '[{"kategorie": "wörtlich", "text": "\"Bevor du sich rasierst, solltest du dir das Gesicht gut mit Seife einreiben!\"  2. Vor der Rasur solltest du dein Gesicht gründlich mit Seife einreiben!  3. Bevor du rasierst, solltest du dein Gesicht gründlich einschäumen!"}]'::jsonb, ''),
  ('den-hob-i-uandlich-eigsaafnd', 'Den hob I uandlich eigsaafnd!', '', '', '', 'Wiener Gaunersprache', 'Den habe ich ordentlich eingeseift!', '[{"kategorie": "wörtlich", "text": "\"Den habe ich ordentlich um den Finger gewickelt!\"  2. Den hab ich langsam weichgekocht!  3. Den hab ich mir zurechtgequatscht!  4. Den habe ich voll rumgekriegt!"}]'::jsonb, ''),
  ('loss-di-von-dem-ned-eisaafn-dea-reed-vueue-owa-maands-ned-eanst', 'Loss di von dem ned eisaafn - dea reed vüü, owa maands ned eanst!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Lass dich von dem nicht einseifen, der redet viel, aber meint es nicht ernst!', '[{"kategorie": "wörtlich", "text": "\"Lass dich von dem nicht um den Finger wickeln - der redet viel, aber meint es nicht ernst!\"  2. Lass dich von dem nicht weichkochen - der redet nur heiße Luft!  3. Fall auf den nicht rein - der labert viel, meint aber nix ernst!"}]'::jsonb, ''),
  ('dea-hod-de-schaeaefin-richtig-eibroodn-bis-eam-a-gehoidseahoehung-geem-hod', 'Dea hod de Schääfin richtig eibroodn, bis eam a Gehoidseahöhung geem hod!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der hat die Chefin richtig eingebraten, bis sie ihm eine Gehaltserhöhung gegeben hat!', '[{"kategorie": "wörtlich", "text": "Der hat die Chefin so lange weichgekocht, bis sie ihm die Gehaltserhöhung genehmigt hat!  2. Er hat der Chefin so viel Honig ums Maul geschmiert, dass sie ihm schließlich ''ne Gehaltserhöhung zugesagt hat!  3. Der hat die Chefin so lange eingelullt, bis sie ihm die Gehaltserhöhung bewilligt hat!"}]'::jsonb, ''),
  ('dea-hod-si-bei-da-neichn-kollegin-eibroodn-wiara-leifiga-hund', 'Dea hod si bei da neichn Kollegin eibroodn wiara leifiga Hund!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der hat sich bei der neuen Kollegin eingebraten wie ein läufiger Hund!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich an die neue Kollegin rangewanzt wie ein läufiger Hund!\"  2. Kaum war die neue Kollegin da, hat er sie auch schon wie ein Irrer angebaggert!  3. Der hat sich auf die neue Kollegin geschmissen, als wär sie das letzte Weib auf Erden!"}]'::jsonb, 'si bei wem eibroodn'),
  ('zeaschd-muassd-des-fleisch-guad-eibroodn-bevuas-das-in-oofn-gibsd', 'Zeaschd muassd des Fleisch guad eibroodn, bevuas das in Oofn gibsd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zuerst musst du das Fleisch gut einbraten, bevor du es in den Ofen gibst!', '[{"kategorie": "wörtlich", "text": "\"Zuerst musst du das Fleisch scharf anbraten, bevor es in den Ofen kommt!\"  2. Brate das Fleisch zuerst kräftig an, dann ab damit in den Ofen!  3. Erst wird das Fleisch in der Pfanne angebraten, dann kommt es in den Ofen!"}]'::jsonb, ''),
  ('si-bei-wem-eibroodn', 'si bei wem eibroodn', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'sich bei jemandem einbraten', '[{"kategorie": "wörtlich", "text": "\"sich an jemanden heranmachen\", \"sich an jemanden ranschmeißen\""}, {"kategorie": "", "text": "jemanden becircen, einlullen, umgarnen, umwerben"}, {"kategorie": "", "text": "jemanden anmachen, anbaggern, mit jemandem [[anbandeln]]"}]'::jsonb, ''),
  ('hau-doch-des-oide-kreiwae-endlich-weg-a-raparatua-zoid-si-do-nimma-aus', 'Hau doch des oide Kreiwä endlich weg - a Raparatua zoid si do nimma aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hau doch das alte Kreibel endlich weg - eine Reparatur zahlt sich da nicht mehr aus!', '[{"kategorie": "wörtlich", "text": "\"Wirf doch dieses ausrangierte Altgerät endlich weg - eine Reparatur zahlt sich da nicht mehr aus!\"  2. Entsorg dieses veraltete Gerät endlich – eine Reparatur wäre wirtschaftlich nicht sinnvoll!  3. Schmeiß das alte Teil endlich weg – eine Reparatur lohnt sich da nicht mehr!"}]'::jsonb, ''),
  ('si-hod-eam-eibremsn-miassn-sunst-haeda-iwareagiad', 'Si hod eam eibremsn miassn, sunst häda iwareagiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie hat ihn einbremsen müssen, sonst hätte er überreagiert!', '[{"kategorie": "wörtlich", "text": "\"Sie musste ihn zurückhalten, sonst hätte er überreagiert!\"  2. Sie musste ihn beruhigen, sonst wäre er über das Ziel hinausgeschossen!  3. Sie hat ihn bremsen müssen, sonst wäre er ausgerastet!"}]'::jsonb, ''),
  ('eibremsn-losst-si-des-oide-kreiwae-nua-schwea-waeu-de-raafn-kaum-mea-an-grip-haum', 'Eibremsn losst si des oide Kreiwä nua schwea, wäu de Raafn kaum mea an Grip haum!', '', '', '', 'Wiener Mechaniker-Slang', 'Einbremsen lässt sich das alte Kreibel nur schwer, weil die Reifen kaum mehr ''nen Grip haben!', '[{"kategorie": "wörtlich", "text": "\"Die alte Schrottkiste lässt sich nur schwer abbremsen, da die Reifen kaum noch Bodenhaftung haben!\"  2. Die Bremsleistung bei dieser alten Rostlaube ist ziemlich eingeschränkt, weil die Reifen stark abgenutzt und kaum noch griffig sind!  3. Das alte Ding bremst kaum noch, weil die Reifen fast glatt sind!"}]'::jsonb, ''),
  ('i-hob-mi-eibremsn-miassn-sunst-haed-i-eam-no-wos-gsogd', 'I hob mi eibremsn miassn, sunst häd I eam no wos gsogd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab mich einbremsen müssen, sonst hätt'' ich ihm noch was gesagt!', '[{"kategorie": "wörtlich", "text": "\"Ich musste mich zurückhalten, sonst hätt'' ich ihm noch was gesagt!\"  2. Ich musste mich beherrschen, sonst hätte ich noch etwas Unüberlegtes gesagt!  3. Ich habe mich bewusst zurückgenommen, um nicht ausfallend zu werden!"}]'::jsonb, 'si eibremsn'),
  ('si-eibremsn', 'si eibremsn', '', '', '', 'Grundwortschatz Wienerisch', 'sich einbremsen', '[{"kategorie": "wörtlich", "text": "\"sich einbremsen\" (vom mittelhochdeutschen \"īn brēmen\"=\"einengen\")"}, {"kategorie": "allg.", "text": "\"sich einbremsen\", langsamer werden, die Geschwindigkeit drosseln"}, {"kategorie": "fig.", "text": "sich einkriegen, sich zurückhalten, sich beherrschen, sich zurücknehmen"}]'::jsonb, 'I hob mi eibremsn miassn, sunst häd I eam no wos gsogd!'),
  ('vua-da-naeaechsdn-kuavn-muassdi-eibremsn-sonst-dareidsd-das-ned', 'Vua da näächsdn Kuavn muassdi eibremsn, sonst dareidsd das ned!', '', '', '', 'Wiener Mechaniker-Slang', 'Vor der nächsten Kurve musst du dich einbremsen, sonst derreitest du sie nicht!', '[{"kategorie": "wörtlich", "text": "\"Vor der nächsten Kurve musst du abbremsen, sonst schaffst du sie nicht!\"  2. Mach langsam vor der Kurve, sonst landest im Straßengraben!  3. Reduziere dein Tempo vor der nächsten Kurve, sonst kommst du da nicht rum!"}]'::jsonb, 'si eibremsn'),
  ('si-eiranftln', 'si eiranftln', '', '', '', 'Grundwortschatz Wienerisch', 'sich einranfteln', '[{"kategorie": "wörtlich", "text": "\"einen Rand um sich herum machen\" (vom mittelhochdeutschen Wort \"ranft\" = \"Rand\")"}, {"kategorie": "fig.", "text": "\"sich einranfteln\", \"sich in eine Ecke zurückziehen\", \"sich in sein Schneckenhaus zurückziehen\", sich abschotten, sich verschanzen, sich verbarrikadieren"}]'::jsonb, 'Si hod si in iara eiganan Wööd eigranftld und kaan mea zuwelossn!'),
  ('si-hod-si-in-iara-eiganan-woeoed-eigranftld-und-kaan-mea-zuwelossn', 'Si hod si in iara eiganan Wööd eigranftld und kaan mea zuwelossn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie hat sich in ihrer eigenen Welt eingeranftelt und keinen mehr an sich rangelassen!', '[{"kategorie": "wörtlich", "text": "\"Sie hat sich in ihre eigene Welt zurückgezogen und niemanden mehr an sich herangelassen!\"  2. Sie hat sich in ihr Schneckenhaus verkrochen und keinen mehr an sich herangelassen!  3. Sie hat komplett dichtgemacht und nur noch in ihrer Blase gelebt!"}]'::jsonb, 'si eiranftln'),
  ('du-muassd-in-saum-ranftln-damita-ned-ausfraunsd', 'Du muassd in Saum ranftln, damita ned ausfraunsd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Du musst den Saum ranfteln, damit er nicht ausfranst!', '[{"kategorie": "wörtlich", "text": "\"Du musst den Saum einfassen, damit er nicht ausfranst!\"  2. Fass den Stoffrand sauber ein, sonst löst er sich mit der Zeit!  3. Gib dem Saum eine saubere Kante, dann hält’s besser!"}]'::jsonb, ''),
  ('du-muassd-in-saum-eiranftln-damita-ned-ausfraunsd', 'Du muassd in Saum eiranftln, damita ned ausfraunsd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Du musst den Saum einranfteln, damit er nicht ausfranst!', '[{"kategorie": "wörtlich", "text": "\"Du musst den Saum einfassen, damit er nicht ausfranst!\"  2. Fass den Stoffrand sauber ein, sonst löst er sich mit der Zeit!  3. Gib dem Saum eine saubere Kante, dann hält’s besser!"}]'::jsonb, ''),
  ('beim-brood-is-wiarim-leebm-wea-zspaeaed-kummd-kriagd-nua-no-s-ranftl', 'Beim Brood is wiarim Leebm - wea zspääd kummd, kriagd nua no s''Ranftl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Beim Brot ist''s wie im Leben: Wer zu spät kommt, kriegt nur mehr das Ranftl!', '[{"kategorie": "wörtlich", "text": "\"Beim Brot ist''s wie im Leben: Wer zu spät kommt, kriegt nur mehr das harte Eck vom Brot!\"  2. Beim Brot ist es wie im Leben: Wer zu spät kommt, muss mit dem Rest vorliebnehmen!  3. Im Leben ist''s wie beim Essen – wer zu spät kommt, kriegt nur, was übrig bleibt!"}]'::jsonb, ''),
  ('si-fadisian', 'si fadisian', '', '', '', 'Grundwortschatz Wienerisch', 'sich fadisieren', '[{"kategorie": "wörtlich", "text": "\"sich langweilen\" (vom Adjektiv \"fad\"=\"langweilig\" mit der Verbalendung \"-isieren\")"}, {"kategorie": "allg.", "text": "vor Langeweile fast einschlafen, sich zu Tode langweilen, nichts mit sich anzufangen wissen, [[des]] faade Aug haum"}]'::jsonb, 'I hock do wiara Hendl aum Rost und fadisia mi duachs Wochnend!'),
  ('i-hock-do-wiara-hendl-aum-rost-und-fadisia-mi-duachs-wochnend', 'I hock do wiara Hendl aum Rost und fadisia mi duachs Wochnend!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hock da wie ein Hendl am Rost und fadisiere mich durchs Wochenende!', '[{"kategorie": "wörtlich", "text": "\"Ich hock da wie bestellt und nicht abgeholt und sterbe schon das ganze Wochenende vor Langeweile !\"  2. Ich gammel mich durchs Wochenende und weiß vor lauter Langeweile nicht, was ich tun soll!  3. Ich häng hier rum wie ein schlapper Waschlappen und langweile mich schon das ganze Wochenende!"}]'::jsonb, 'si fadisian'),
  ('du-bist-a-rechta-falott-zum-geanhaum-und-zum-fiachtn-zgleich', 'Du bist a rechta Falott - zum Geanhaum und zum Fiachtn zgleich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Du bist ein rechter Falott - zum Gernhaben und zum Fürchten zugleich!', '[{"kategorie": "wörtlich", "text": "\"Du bist ein echter Strizzi - charmant, aber gefährlich!\"  2. Du bist so ein typischer Hallodri – zum Knuddeln und zum Fürchten zugleich!  3. Du bist der Typ, vor dem dich deine Mutter warnt – aber den sie insgeheim trotzdem mag!"}]'::jsonb, ''),
  ('du-klaana-falott-du', 'Du klaana Falott, du!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Du kleiner Falott, du!', '[{"kategorie": "wörtlich, scherzhaft auch in Bezug auf Kinder", "text": "\"Du kleiner Halunke!\"  2. Du kleines Schlitzohr!  3. Du kleiner Schlawiner!"}]'::jsonb, ''),
  ('zum-glick-hauma-no-den-oidn-fleischwoif-mit-dem-lossd-si-ollas-schee-faschian', 'Zum Glick hauma no den oidn Fleischwoif - mit dem lossd si ollas schee faschian!', '', '', '', 'Wiener Fleischhauer-Slang', 'Zum Glück haben wir noch den alten Fleischwolf – damit lässt sich alles schön faschieren!', '[{"kategorie": "wörtlich", "text": "\"Zum Glück haben wir noch den alten Fleischwolf – damit lässt sich das Fleisch hervorragend zerkleinern!\"  2. Gut, dass wir den alten Fleischwolf noch haben – er macht feines Faschiertes!  3. Gott sei Dank haben wir den alten Fleischwolf noch – der zerlegt das Fleisch besser als jede moderne Maschine!"}]'::jsonb, ''),
  ('i-kennt-eam-faschian', 'I kennt eam faschian!', '', '', '', 'Wiener Gaunersprache', 'Ich könnte ihn faschieren!', '[{"kategorie": "wörtlich", "text": "\"Ich könnte ihn durch den Fleischwolf drehen!\"  2. Ich könnte ihn in Stücke reißen!  3. Ich würd ihn am liebsten in der Luft zerreißen!"}]'::jsonb, ''),
  ('i-kennt-eam-in-d-faschiamaschin-schmeissn', 'I kennt eam in d''Faschiamaschin schmeissn!', '', '', '', 'Wiener Gaunersprache', 'Ich könnte ihn in die Faschiermaschine schmeißen!', '[{"kategorie": "wörtlich", "text": "\"Ich könnte ihn durch den Fleischwolf drehen!\"  2. Ich könnte ihn in Stücke reißen!  3. Ich würd ihn am liebsten in der Luft zerreißen!"}]'::jsonb, ''),
  ('faschiade-laawaln', 'faschiade Laawaln', '', '', '', 'Wiener Küche & Gaumenfreuden', 'faschierte Laberln', '[{"kategorie": "wörtlich", "text": "\"faschierte Laibchen\" (von \"faschieren\"=\"Fleisch durch den Fleischwolf drehen\" und \"Laberl\"=\"kleiner Laib\")"}, {"kategorie": "Gastronomie", "text": "\"Fleischlaibchen\", [[Fleischlaawaln]] (Laibchen aus faschiertem Fleisch, eingeweichtem Weißbrot, Ei und Gewürzen geformte Laibchen),  \"Hackfleischlaibchen\", (Deutschland): \"Frikadellen\", (Schweiz): \"Hacktäschli\""}]'::jsonb, 'Faschiade Laawaln mit an Eadäpfäpiree san a echta Klassika unsara Wiina Wiatshauskuchl!'),
  ('ausn-faschiadn-moch-ma-heite-fleischlaawaln', 'Ausn Faschiadn moch ma heite Fleischlaawaln!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Aus dem Faschierten machen wir heute Fleischlaberln!', '[{"kategorie": "wörtlich", "text": "\"Aus dem Faschierten machen wir heute Fleischlaibchen!\"  2. Das Faschierte verarbeiten wir heute mit Ei und Semmelbröseln zu saftigen Fleischlaberln!  3. (Deutschland): \"Aus dem Hackfleisch bereiten wir heute klassische Frikadellen zu!"}]'::jsonb, ''),
  ('im-fosching-deaf-ma-endlich-so-tuan-ois-warad-ma-wea-gaunz-aundara', 'Im Fosching deaf ma endlich so tuan, ois warad ma wea gaunz aundara!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Fasching darf man endlich so tun, als wäre man wer ganz anderer!', '[{"kategorie": "wörtlich", "text": "\"Im Fasching darf man endlich so tun, als wär man jemand ganz anderes!\"  2. Fasching ist die Zeit, in der jeder endlich sein darf, wer er will!  3. Im Fasching darf man in jede Rolle schlüpfen und für einen Moment ein anderer Mensch sein!"}]'::jsonb, ''),
  ('zu-fosching-isst-ma-in-oestarreich-traditionell-foschingskropfn', 'Zu Fosching isst ma in Östarreich traditionell Foschingskropfn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zu Fasching isst man in Österreich traditionell Faschingskrapfen!', '[{"kategorie": "wörtlich", "text": "\"In Österreich gehören Faschingskrapfen traditionell zur Faschingszeit dazu!\"  2. Zur Faschingszeit isst man in Österreich typischerweise Faschingskrapfen mit Marillenmarmelade!  3. Faschingszeit ist Krapfenzeit – zumindest hier bei uns in Österreich!"}]'::jsonb, ''),
  ('foschingsdiinstog-is-da-toog-aun-dem-sogoa-mei-schaeaef-an-kauboihuat-troogd', 'Foschingsdiinstog is da Toog, aun dem sogoa mei Schääf an Kauboihuat troogd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Faschingsdienstag ist der Tag, an dem sogar mein Chef einen Cowboyhut trägt!', '[{"kategorie": "wörtlich", "text": "\"Karnevalsdienstag ist der Tag, an dem sogar mein Chef einen Cowboyhut trägt!\"  2. Am Faschingsdienstag wirft sogar mein Chef die Krawatte weg und setzt sich einen Cowboyhut auf!  3. Wenn mein Chef mit Cowboyhut auftaucht, dann weißt du: Es ist Faschingsdienstag!"}]'::jsonb, ''),
  ('aum-oschamittwoch-ruafd-de-kiachn-zu-besinnung-zu-buusse-und-zum-fostn-auf', 'Aum Oschamittwoch ruafd de Kiachn zu Besinnung, zu Buusse und zum Fostn auf!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Am Aschermittwoch ruft die Kirche zu Besinnung, zu Buße und zum Fasten auf!', '[{"kategorie": "wörtlich", "text": "\"Am Aschermittwoch beginnt für Christen die Zeit der Besinnung, der Buße und des Fastens!\"  2. Am Aschermittwoch lädt die Kirche zur Umkehr, zur Selbstreflexion und zum Verzicht ein!  3. Der Aschermittwoch steht im Zeichen der geistigen Erneuerung und des freiwilligen Verzichts! 8"}]'::jsonb, ''),
  ('mariae-himmaefoat', 'Mariä Himmäfoat', 'die', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Mariä Himmelfahrt', '[{"kategorie": "wörtlich", "text": "\"Maria Himmelfahrt\" (vom mittelhochdeutschen \"Marien himelfart\"=\"Mariens Himmelfahrt\")"}, {"kategorie": "rel.", "text": "\"christlicher Hochfesttag am 15. August\" (leibliche Aufnahme der Jungfrau Maria in den Himmel), \"Mariä Aufnahme in den Himmel\", (lateinisch): \"Assumptio Beatae Mariae Virginis\""}]'::jsonb, 'De Kiachn eead zu Mariä Himmäfoat de Muttagottes ois Easchde unta de Ealöösdn!'),
  ('de-kiachn-eead-zu-mariae-himmaefoat-de-muttagottes-ois-easchde-unta-de-ealoeoesdn', 'De Kiachn eead zu Mariä Himmäfoat de Muttagottes ois Easchde unta de Ealöösdn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die Kirche ehrt zu Mariä Himmelfahrt die Muttergottes als die Erste unter den Erlösten!', '[{"kategorie": "wörtlich", "text": "\"Zu Mariä Himmelfahrt feiert die Kirche die Aufnahme der Gottesmutter als Erste der Erlösten in den Himmel!\"  2. Maria Muttergottes wird an Mariä Himmelfahrt als Erste der Erlösten und als Königin des Himmels verehrt!  3. Zu Mariä Himmelfahrt feiert die Kirche Maria als die Erste, die in der Fülle der Erlösung an Gottes Herrlichkeit teilhat!"}]'::jsonb, 'Mariä Himmäfoat'),
  ('de-drei-weisn-aus-moagnlaund-bringan-am-dreikeenigstoog-iare-goobn-goid-weirauch-und-myrre', 'De drei Weisn aus Moagnlaund bringan am Dreikeenigstoog iare Goobn: Goid, Weirauch und Myrre!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die drei Weisen aus dem Morgenland bringen am Dreikönigstag ihre Gaben: Gold, Weihrauch und Myrrhe!', '[{"kategorie": "wörtlich", "text": "\"Die drei Gaben der Weisen aus dem Morgenland – Gold, Weihrauch und Myrrhe – sind das traditionelle Symbol des Dreikönigstags!\"  2. Am Dreikönigstag bringen die Weisen aus dem Morgenland dem menschgewordenen Gott ihre kostbaren Zeichen der Huldigung: Gold, Weihrauch und Myrrhe!  3. Die biblische Erzählung vom Dreikönigstag berichtet von drei Weisen aus dem Morgenland, die wertvolle Geschenke zum Jesuskind in der Krippe bringen: Gold, Weihrauch und Myrrhe!"}]'::jsonb, ''),
  ('mariae-empfaengnis', 'Mariä Empfängnis', 'die', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Mariä Empfängnis', '[{"kategorie": "wörtlich", "text": "\"Maria Empfängnis\" (vom mittelhochdeutschen \"unsêr frouwen reine êmpfengnisse\"=\"Mariä reine Empfängnis\")"}, {"kategorie": "rel.", "text": "katholischer Hochfesttag (8. Dezember), \"Fest der unbefleckten Empfängnis Mariens\" (=der Glaube, dass Maria vom ersten Moment ihres Daseins an von der Erbsünde frei bewahrt wurde, um so würdig zur Mutter Jesu werden zu können), \"Fest der Immaculata\" (Maria Empfängnis“ meint NICHT die Empfängnis Jesu durch Maria, sondern viemehr die Empfängnis Marias selbst – also im Schoß ihrer Mutter, der heiligen Anna)"}]'::jsonb, 'Mariä Empfängnis is da Toog, aun dem de Kiachn feiad, dass Maria von Aufaung au frei von da Eabsünd woa!'),
  ('mariae-empfaengnis-is-da-toog-aun-dem-de-kiachn-feiad-dass-maria-von-aufaung-au-frei-von-da-eabsuend-woa', 'Mariä Empfängnis is da Toog, aun dem de Kiachn feiad, dass Maria von Aufaung au frei von da Eabsünd woa!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Mariä Empfängnis ist der Tag, an dem die Kirche feiert, dass Maria von Anfang an frei von der Erbsünde war!', '[{"kategorie": "wörtlich", "text": "\"Mariä Empfängnis ist das Hochfest, an dem die Kirche feiert, dass Maria vom ersten Augenblick ihres Daseins an durch Gottes Gnade frei von der Erbsünde war!\"  2. Der Feiertag Mariä Empfängnis würdigt Maria als die einzige, die nie durch die Erbsünde belastet war!  3. Am 8. Dezember feiert die Kirche, dass Maria von Gott ganz rein und unbefleckt erschaffen wurde!"}]'::jsonb, 'Mariä Empfängnis'),
  ('de-kinda-haum-beim-umzug-aum-poimsuundog-bunt-gschmickde-poimkatzalzweig-troong', 'De Kinda haum beim Umzug aum Poimsuundog bunt gschmickde Poimkatzalzweig troong!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die Kinder haben beim Umzug am Palmsonntag bunt geschmückte Palmkatzerlzweige getragen!', '[{"kategorie": "wörtlich", "text": "\"Die Kinder trugen beim Umzug am Palmsonntag bunt geschmückte Palmkätzchenzweige!\"  2. Beim Palmsonntagsumzug hielten die Kinder farbenfroh verzierte Palmkätzchen in den Händen!  3. Am Palmsonntag marschierten die Kinder bei der Festtagsprozession mit bunt geschmückten Weidenzweigen durch die Straßen!"}]'::jsonb, ''),
  ('aum-griindunnastog-bock-ma-imma-a-aafochs-flaadnbrood', 'Aum Griindunnastog bock ma imma a aafochs Flaadnbrood!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Am Gründonnerstag backen wir immer ein einfaches Fladenbrot!', '[{"kategorie": "wörtlich", "text": "\"Am Gründonnerstag backen wir traditionell ein einfaches Fladenbrot!\"  2. Wie jedes Jahr legen wir am Gründonnerstag ein schlichtes Fladenbrot in den Ofen – ein Brot des Gedenkens!  3. Am Gründonnerstag, dem Abend vor dem Leiden, teilen wir das schlichte Fladenbrot, das wir im Ofen selbst gebacken haben!"}]'::jsonb, ''),
  ('koafreidog-is-da-toog-aun-dem-de-glockn-schweing', 'Koafreidog is da Toog, aun dem de Glockn schweing!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Karfreitag ist der Tag, an dem die Glocken schweigen!', '[{"kategorie": "wörtlich", "text": "\"Karfreitag ist der Tag, an dem die Kirchenglocken als Zeichen der Trauer verstummen!\"  2. Die Glocken bleiben am Karfreitag stumm – als Ausdruck der Trauer über den Kreuzestod Christi!  3. An Karfreitag herrscht Stille in den Kirchen – und auch die Glocken schweigen!"}]'::jsonb, ''),
  ('in-da-koawochn-begleitn-de-christn-in-jesus-auf-sein-weeg-zum-kreiz', 'In da Koawochn begleitn de Christn in Jesus auf sein Weeg zum Kreiz!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'In der Karwoche begleiten die Christen Jesus auf seinem Weg zum Kreuz!', '[{"kategorie": "wörtlich", "text": "\"In der Karwoche folgen die Gläubigen dem Herrn auf seinem Weg zum Kreuz!\"  2. Christen nehmen in der Karwoche teil am Opferweg des Herrn!  3. In der Karwoche gehen Christen Schritt für Schritt mit Jesus in das Dunkel von Golgatha!"}]'::jsonb, ''),
  ('im-oostafeia-faungds-neiche-liachd-au-des-christus-ois-liachd-da-woeoed-vakoeapad', 'Im Oostafeia faungds neiche Liachd au, des Christus ois Liachd da Wööd vaköapad!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Im Osterfeuer fängt das neue Licht an, das Christus als Licht der Welt verkörpert!', '[{"kategorie": "wörtlich", "text": "\"Im Osterfeuer beginnt das neue Licht, das Christus - das Licht der Welt - verkörpert!\"  2. Aus dem Osterfeuer entspringt das österliche Licht, das Christus als das Licht der Welt offenbart!  3. Das Licht, das am Osterfeuer entzündet wird, steht für Christus, das Licht der Welt!"}]'::jsonb, ''),
  ('wia-segnan-jeds-joa-unsa-ostalaumm-bei-da-mess-in-da-oostanochd', 'Wia segnan jeds Joa unsa Ostalaumm bei da Mess in da Oostanochd!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Wir segnen jedes Jahr unser Osterlamm bei der Messe in der Osternacht!', '[{"kategorie": "wörtlich", "text": "\"Wir segnen jedes Jahr unser Osterlamm beim Gottesdienst in der Osternacht!\"  2. Zur Osternacht bringen wir unser Osterlamm mit zur Segnung in die Kirche!  3. Als Zeichen des österlichen Glaubens lassen wir das Osterlamm im Osternachtsgottesdienst segnen!"}]'::jsonb, ''),
  ('im-oostaeia-liigd-de-schduelle-vaheissung-des-leebms-des-ausn-tood-eawocht', 'Im Oostaeia liigd de schdülle Vaheissung des Leebms, des ausn Tood eawocht!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Im Osterei liegt die stille Verheißung des Lebens, das aus dem Tod erwacht!', '[{"kategorie": "wörtlich", "text": "\"Das Osterei birgt in sich die stille Verheißung des Lebens, das aus dem Tod erwacht!\"  2. Im Osterei schläft das Licht des Lebens, das still die Dunkelheit durchbricht!  3. Das bunte Osterei erinnert uns daran, dass das Leben immer wieder neu beginnt!"}]'::jsonb, ''),
  ('oostan-vakuendet-in-siig-des-leebms-iwan-tood', 'Oostan vakündet in Siig des Leebms iwan Tood!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Ostern verkündet den Sieg des Lebens über den Tod!', '[{"kategorie": "wörtlich", "text": "\"Ostern markiert den Wendepunkt vom Tod zum Leben!\"  2. Im Osterfest feiern Christen die Auferstehung – den endgültigen Sieg Gottes über den Tod!\"  3. Ostern gibt Hoffnung, dass das Leben weitergeht – selbst nach dem Tod"}]'::jsonb, ''),
  ('weinochtn-oone-grissbaam-und-liachdln-warad-fia-mi-undenkboa', 'Weinochtn oone Grissbaam und Liachdln warad fia mi undenkboa!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Weihnachten ohne Christbaum und Lichter wäre für mich undenkbar!', '[{"kategorie": "wörtlich", "text": "\"Weihnachten ohne Tannenbaum und Lichter wäre für mich undenkbar!\"  2. Ein Weihnachtsfest ohne Christbaum und leuchtende Kerzen wäre für mich wie Winter ohne Schnee!  3. Ich kann mir Weihnachten ohne Lichter und Baum einfach nicht vorstellen!"}]'::jsonb, ''),
  ('heiliga-oobnd', 'Heiliga Oobnd', 'der', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Heiliger Abend', '[{"kategorie": "wörtlich", "text": "\"Heiliger Abend\" (vom mittelhochdeutschen \"wîhe abent\"=\"geweihter Abend\")"}, {"kategorie": "rel.", "text": "\"Heiligabend\" (wird am 24. Dezember gefeiert und bildet den Vorabend des Weihnachtsfestes), \"Christabend\", \"Christnacht\", \"Nacht der Geburt Christi\" (Abend, an dem die Geburt Jesu Christi gefeiert wird – häufig in einer feierlichen Christmette oder Christnacht), \"Heilige Nacht\""}, {"kategorie": "allg.", "text": "Weihnachtsabend, Abend der Bescherung (geprägt von Stille, Lichtern, Besinnung und auch von Geschenken und familiärem Beisammensein)"}]'::jsonb, 'Da Heilige Oobnd is fia mi da scheenste Toog im Joa!'),
  ('da-heilige-oobnd-is-fia-mi-da-scheenste-toog-im-joa', 'Da Heilige Oobnd is fia mi da scheenste Toog im Joa!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Der Heilige Abend ist für mich der schönste Tag im Jahr!', '[{"kategorie": "wörtlich", "text": "\"Der allerschönste Tag im Jahr ist für mich der Heilige Abend!\"  2. Für mich ist der Heilige Abend der wunderbarste Moment des ganzen Jahres!  3. Am Heiligen Abend wird der Himmel greifbar – für mich ist das das Größte im Jahr!"}]'::jsonb, 'Heiliga Oobnd'),
  ('de-tiarln-vom-adventskalenda-leichtn-wia-schdeandaln-aufm-weeg-zua-krippn', 'De Tiarln vom Adventskalenda leichtn wia Schdeandaln aufm Weeg zua Krippn!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die Türchen des Adventskalenders leuchten wie Sternchen auf dem Weg zur Krippe!', '[{"kategorie": "wörtlich", "text": "\"Wie Sterne auf dem Weg zur Krippe leuchten die Türchen des Adventskalenders!\"  2. Wie kleine Sterne weisen die Türchen des Adventskalenders den Pfad zur Heiligen Nacht!  3. Die Türchen des Adventskalenders sind wie geistige Lichter auf dem Pfad zur Ankunft des Herrn!"}]'::jsonb, ''),
  ('de-keazn-aum-adventskraunz-leichtn-wiara-tiarl-zwischn-dunkl-und-liachd', 'De Keazn aum Adventskraunz leichtn wiara Tiarl zwischn Dunkl und Liachd!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die Kerzen am Adventskranz leuchten wie ein Tor zwischen Dunkel und Licht!', '[{"kategorie": "wörtlich", "text": "\"Der Adventskranz leuchtet wie ein Tor zwischen Dunkel und Licht!\"  2. Der Adventskranz erstrahlt als stiller Bogen zwischen Nacht und Morgenlicht!  3. Der Adventskranz weist den Weg vom Dunkel der Welt zum Licht Christi!"}]'::jsonb, ''),
  ('in-da-schdaadn-zeit-leichtn-in-an-jedn-fensta-liachtaboeoeng-und-schdean', 'In da schdaadn Zeit leichtn in an jedn Fensta Liachtabööng und Schdean!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Während der Adventszeit leuchten in jedem Fenster Lichterbögen und Sterne!', '[{"kategorie": "wörtlich", "text": "\"In der stillen Adventszeit leuchten Lichter und Sterne in jedem Fenster wie Hoffnungszeichen!\"  2. Fenster verwandeln sich in der Adventszeit in strahlende Bilder aus Licht und Sternenglanz!  3. Die Adventszeit lässt Fenster erstrahlen – als Zeichen der Vorbereitung auf das göttliche Licht!"}]'::jsonb, 'de schdaade Zeit'),
  ('de-schdaade-zeit', 'de schdaade Zeit', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'die stade Zeit', '[{"kategorie": "wörtlich", "text": "\"die ruhige Zeit\""}, {"kategorie": "rel.", "text": "\"Adventszeit\", \"Zeit der Ankunft\" (Zeitraum von etwa vier Wochen vor Weihnachten, in dem Christen die Ankunft Jesu Christi erwarten und sich innerlich auf das Weihnachtsfest vorbereiten. Sie ist zugleich eine Zeit der Besinnung, der Hoffnung und des Lichts in der Dunkelheit des Winters), (lateinisch): \"Adventus Domini\" (Ankunft des Herrn), \"Vorbereitungszeit auf Weihnachten\""}]'::jsonb, 'In da schdaadn Zeit leichtn in an jedn Fensta Liachtabööng und Schdean!'),
  ('in-da-oostanochd-vuam-oostasuundog-wiads-oostafeia-auzind', 'In da Oostanochd vuam Oostasuundog wiads Oostafeia auzind!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'In der Osternacht vor Ostersonntag wird das Osterfeuer entzündet!', '[{"kategorie": "wörtlich", "text": "\"In der Osternacht, die in den Ostersonntag führt, wird das Osterfeuer entzündet!\"  2. In der Nacht auf Ostersonntag wird traditionell das Osterfeuer als Zeichen der Auferstehung entzündet!  3. Mit dem Einbruch der Osternacht wird das Licht des Osterfeuers als Symbol des Lebens entfacht!"}]'::jsonb, ''),
  ('aum-oostamoondog-gedenkn-de-christn-in-jesus-wiara-aan-toog-noch-seina-aufeaschdeehung-vua-zwaa-von-seine-juenga-easchiinan-is', 'Aum Oostamoondog gedenkn de Christn in Jesus, wiara aan Toog noch seina Aufeaschdeehung vua zwaa von seine Jünga easchiinan is!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Am Ostermontag gedenken die Christen der Erscheinungen Jesu vor zwei seiner Jünger einen Tag nach seiner Auferstehung!', '[{"kategorie": "wörtlich", "text": "\"Die Christen gedenken am Ostermontag der Erscheinungen Jesu vor zwei seiner Jünger einen Tag nach der Auferstehung!\"  2. Am Ostermontag erinnern sich Christen an die Begegnungen des auferstandenen Jesus mit zwei seiner Jünger!\"  3. Christus offenbart sich am Ostermontag als der lebendige Herr vor zwei seiner Jünger – das feiern die Gläubigen im Gedenken daran!"}]'::jsonb, ''),
  ('pfingstn-soi-uns-draun-erinnan-dass-gottes-geist-unta-uns-leebd-und-wiakd', 'Pfingstn soi uns draun erinnan, dass Gottes Geist unta uns leebd und wiakd!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Pfingsten soll uns daran erinnern, dass Gottes Geist unter uns lebt und wirkt!', '[{"kategorie": "wörtlich", "text": "\"Pfingsten erinnert uns daran, dass Gottes Geist unter uns lebt und wirkt!\"  2. Pfingsten ist das Fest, an dem wir die bleibende Gegenwart des Heiligen Geistes feiern!  3. Pfingsten soll uns zeigen, dass der Geist Gottes nicht fern, sondern mitten unter uns ist!"}]'::jsonb, ''),
  ('aum-pfingstsuundog-schmueck-ma-in-hauseingaung-mit-frische-biaknzweig', 'Aum Pfingstsuundog schmück ma in Hauseingaung mit frische Biaknzweig!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Am Pfingstsonntag schmücken wir den Hauseingang mit frischen Birkenzweigen!', '[{"kategorie": "wörtlich", "text": "\"Am Pfingstsonntag dekorieren wir die Haustür mit jungen Birkenzweigen!\"  2. Am Pfingstsonntag schmücken wir nach altem Brauch den Eingang mit frischen Birkenzweigen!  3. Zum Hochfest Pfingsten tragen wir das Zeichen des neuen Lebens an unsere Tür, indem wir sie mit frischen Birkenzweigen schmücken!"}]'::jsonb, ''),
  ('pfingstmoondog-is-da-toog-aun-dem-da-geist-auf-leisn-fliagln-weidaziagd', 'Pfingstmoondog is da Toog, aun dem da Geist auf leisn Fliagln weidaziagd!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Pfingstmontag ist der Tag, an dem der Geist auf leisen Flügeln weiterzieht!', '[{"kategorie": "wörtlich", "text": "\"Pfingstmontag – der Tag, an dem der Heilige Geist auf leisen Flügeln weiterzieht!\"  2. Am Pfingstmontag spürt man noch das Echo des Geistes, das durch die Welt zieht!  3. Pfingstmontag erinnert uns daran, dass der Geist gekommen ist, um zu bleiben – im Verborgenen!"}]'::jsonb, ''),
  ('da-grissdoog-is-mea-ois-nuara-datum-es-is-a-moment-da-einkea-und-des-wundas', 'Da Grissdoog is mea ois nuara Datum - es is a Moment da Einkea und des Wundas!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Der Christtag ist mehr als ein Datum – er ist ein Moment der Einkehr, des Wunders!', '[{"kategorie": "wörtlich", "text": "\"Der Christtag ist mehr als bloß ein Tag im Kalender – er ist ein Moment der Einkehr, des Wunders!\"  2. Der Christtag ist kein bloßes Datum – er ist ein Fenster, das sich zur Stille und zum Licht öffnet!  3. Der Christtag ist mehr als nur ein Datum - er weckt in uns Andacht, Hoffnung und Wunder!"}]'::jsonb, ''),
  ('aum-schdefaanidoog-brechn-de-bauan-scho-frueue-aum-moagn-zum-schdefaaniritt-duachs-vaschneide-toi-auf', 'Aum Schdefaanidoog brechn de Bauan scho früü aum Moagn zum Schdefaaniritt duachs vaschneide Toi auf!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Am Stefanitag brechen die Bauern schon früh am Morgen zum Stefaniritt durchs verschneite Tal auf!', '[{"kategorie": "wörtlich", "text": "\"Schon im Morgengrauen des heiligen Stephanstags machen sich die Bauern zum Stefaniritt durchs verschneite Tal auf!\"  2. Am Morgen des Stefanitags satteln die Bauern ihre Pferde und ziehen zum feierlichen Ritt durch das weiße Tal!\"  3. Am Tag des Märtyrers Stephanus formiert sich früh die Reiterschar zum Zug durch das winterliche Land!"}]'::jsonb, ''),
  ('zu-suewoeoesta-schrein-olle-prosit-neijoa-und-brunzn-si-daunn-schbaedastns-um-zwoeoefe-gegnseitig-aufd-zaeaechn', 'Zu Süwöösta schrein olle ''Prosit Neijoa!'' und brunzn si daunn schbädastns um zwööfe gegnseitig aufd Zäächn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Zu Silvester schreien alle ''Prosit Neujahr!'' – und brunzen sich dann spätestens um zwölf gegenseitig auf die Zehen!', '[{"kategorie": "wörtlich", "text": "\"Am Silvestertag schreien alle ''Prosit Neujahr!'' – und pissen sich dann spätestens um zwölf gegenseitig auf die Schuhe!\"  2. Silvester: Erst saufen sie sich Mut an, dann grölen sie ''Frohes Neues'' – und dann pinkeln sie sich gegenseitig auf die Knöchel!  3. Am Silvestertag wird geballert, gebechert und gebrüllt, als gäb’s kein Morgen – und nach Mitternacht pisst dann jeder dem Nächsten versehentlich auf die Zehen!"}]'::jsonb, ''),
  ('prosit-neijoa', 'Prosit Neijoa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Prosit Neuhahr!', '[{"kategorie": "wörtlich", "text": "\"Prosit Neujahr!\" (vom lateinischen \"prosit\"=\"es möge zuträglich sein\")"}, {"kategorie": "allg.", "text": "\"Prosit Neujahr!\", \"Ein gesegnetes Neues Jahr!\", [[Guten Rutsch!]]"}]'::jsonb, ''),
  ('da-neijoasdoog-is-da-moagn-danooch-waunnst-zwischn-boellahueuesn-leere-sektfloschn-und-an-schlechtn-gwissn-aufwochst', 'Da Neijoasdoog is da Moagn danooch - waunnst zwischn Böllahüüsn, leere Sektfloschn und an schlechtn Gwissn aufwochst!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Neujahrstag ist der Morgen danach – wenn du zwischen Böllerhülsen, leeren Sektflaschen und einem schlechten Gewissen aufwachst!', '[{"kategorie": "wörtlich", "text": "\"Der Neujahrstag ist der Morgen danach – wenn du aufwachst zwischen Böllerhülsen, leeren Sektflaschen und einem schlechten Gewissen!\"  2. Neujahrstag – der Morgen, an dem du mit pelziger Zunge, Bombenlärm im Kopf und Konfetti im Bauchnabel aufwachst!  3. Am Neujahrstag liegst du da wie ein zerknallter Böller – leer, lautlos und leicht peinlich!"}]'::jsonb, ''),
  ('maria-lichtmess', 'Maria Lichtmess', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Maria Lichtmess', '[{"kategorie": "wörtlich", "text": "\"Maria-Lichtmess-Fest\" (vom mittelhochdeutschen \"liehtmesse unser frouwen\"=\"Lichtmesse unserer Frau\")"}, {"kategorie": "rel.", "text": "\"Fest der Darstellung des Herrn\" (christlicher Feiertag am 2. Februar, der an die Darstellung Jesu im Tempel und die Reinigung Marias erinnert. Es markiert den Abschluss des Weihnachtsfestkreises in der Liturgie), \"Fest der Reinigung Mariens\" (gemäß Lukas 2,22–40 wurde Jesus 40 Tage nach seiner Geburt im Tempel von Jerusalem dargestellt [„geweiht“] und Maria vollzog das rituelle Reinigungsopfer nach jüdischem Gesetz), \"Mariä Reinigung\" (lateinisch: \"Purificatio Mariae\"), \"Unserer Lieben Frau Lichtmess\" (im Tempel von Jerusalem begegneten Jesus und Maria dem Jünger Simeon, der das Kind als „Licht zur Erleuchtung der Heiden“ bezeichnete – daher der Name „Lichtmess“ [von „Lichtmesse“ = Lichtermesse], \"Mariä Lichtmess\""}]'::jsonb, ''),
  ('waunns-zu-maria-lichtmess-schdiamd-und-schneit-is-da-frueueling-nimma-weit', 'Waunns zu Maria Lichtmess schdiamd und schneit, is da Früüling nimma weit!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Wenn''s zu Maria Lichtmess stürmt und schneit, ist der Frühling nicht mehr weit!', '[{"kategorie": "wörtlich", "text": "\"Stürmt’s und schneit’s am Lichtmess-Tag, bringt der März schon Frühlingsschlag!\"  2. Wenn’s zu Lichtmess wintert sehr, kommt der Frühling bald daher!  3. Tobt das Wetter früh im Jahr, wird der Frühling wunderbar!"}]'::jsonb, 'Maria Lichtmess'),
  ('doog-da-oaweid', 'Doog da Oaweid', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Tag der Arbeit', '[{"kategorie": "wörtlich", "text": "\"Tag der Arbeit\" (wobei \"Tag\" für \"Kampftag\" und \"Arbeit\" für \"Arbeiterbewegung\" steht)"}, {"kategorie": "hist.", "text": "\"Tag der Arbeiterbewegung\" (1. Mai, gesetzlicher Feiertag, der weltweit als Symbol- und Kampftag der Arbeiterbewegung gilt), \"Arbeiterkampftag\" (politisch, historisch und gesellschaftlich bedeutend - wird in vielen Ländern mit Demonstrationen, Kundgebungen oder auch Festveranstaltungen begangen), \"Internationaler Feiertag der Arbeit\" (geht auf die Arbeitskämpfe des 19. Jahrhunderts zurück – besonders auf den Generalstreik am 1. Mai 1886 in den USA zur Durchsetzung des Achtstundentags [\"Haymarket Riot in Chicago\"])"}]'::jsonb, 'Waassd, wiar I in Doog da Oaweid feia? Mit Bia, Grüü und oone Schääf!'),
  ('waassd-wiar-i-in-doog-da-oaweid-feia-mit-bia-grueue-und-oone-schaeaef', 'Waassd, wiar I in Doog da Oaweid feia? Mit Bia, Grüü und oone Schääf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Weißt du, wie ich den Tag der Arbeit feiere? Mit Bier, Grill und ohne Chef!', '[{"kategorie": "wörtlich", "text": "\"Tag der Arbeit? Ich feier den mit Bier, Grill und ohne Chef!\"  2. Am 1. Mai tu ich der Arbeit den größten Gefallen: Ich bleib ihr fern und feier ohne Chef!  3. Den Tag der Arbeit feiere ich immer ohne Chef – dafür mit Hopfenkaltgetränk und fleischiger Rebellion!"}]'::jsonb, 'Doog da Oaweid'),
  ('da-saani-hod-ma-n-knechl-gfascht-und-de-schwoellung-is-daunn-aa-glei-zruckgaungan', 'Da Saani hod ma ''n Knechl gfascht, und de Schwöllung is daunn aa glei zruckgaungan!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Sani hat mir den Knöchel gefascht, und die Schwellung ist dann auch gleich zurückgegangen!', '[{"kategorie": "wörtlich", "text": "\"Der Sanitäter hat mir den Knöchel bandagiert, und die Schwellung ist dann auch gleich zurückgegangen!\"  2. Der Knöchel wurde vom Sanitäter fachgerecht komprimiert und fixiert, woraufhin die Schwellung auch gleich nachließ!  3. Der Sanitäter hat mir die Wunde verbunden, und die Schwellung ist dann auch gleich besser geworden!"}]'::jsonb, ''),
  ('des-haus-hauma-in-oidroosa-gschdrichn-und-de-fensta-in-hoeoegrau-gfaschd', 'Des Haus hauma in Oidroosa gschdrichn, und de Fensta in Höögrau gfaschd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Haus haben wir in Altrosa gestrichen und die Fenster in hellgrau gefascht!', '[{"kategorie": "wörtlich", "text": "\"Das Haus wurde in Altrosa gestrichen, und die Fenster wurden in hellgrau gefascht!\"  2. Das Gebäude wurde altrosa verputzt, die Fenster mit hellgrauen Putzbordüren gerahmt!  3. Wir haben das Haus rosa gestrichen und dann graue Umrandungen um die Fenster gezogen – schaut echt gut aus!"}]'::jsonb, ''),
  ('bei-schweere-haustian-miassn-de-schaniaplottn-tiaf-gfaschd-und-vaschraubd-wean', 'Bei schweere Haustian miassn de Schaniaplottn tiaf gfaschd und vaschraubd wean!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Bei schweren Haustüren müssen die Scharnierplatten tief gefascht und verschraubt werden!', '[{"kategorie": "wörtlich", "text": "\"Bei schweren Haustüren müssen die Scharnierplatten tief eingefasst und verschraubt werden!\"  2. Bei großen Haustüren fräst man die Scharnierplatten sauber ein und schraubt sie dann fest!  3. Die Angel muss ordentlich eingefasst und fest angeschraubt sein – sonst hängt die Tür schief!"}]'::jsonb, ''),
  ('da-saani-hod-ma-n-knechl-gfaschtnd-und-de-schwoellung-is-daunn-aa-glei-zruckgaungan', 'Da Saani hod ma ''n Knechl gfaschtnd, und de Schwöllung is daunn aa glei zruckgaungan!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Sani hat mir den Knöchel gefatscht, und die Schwellung ist dann auch gleich zurückgegangen!', '[{"kategorie": "wörtlich", "text": "\"Der Sanitäter hat mir den Knöchel bandagiert, und die Schwellung ist dann auch gleich zurückgegangen!\"  2. Der Knöchel wurde vom Sanitäter fachgerecht komprimiert und fixiert, woraufhin die Schwellung auch gleich nachließ!  3. Der Sanitäter hat mir die Wunde verbunden, und die Schwellung ist dann auch gleich besser geworden!"}]'::jsonb, ''),
  ('des-haus-hauma-in-oidroosa-gschdrichn-und-de-fensta-in-hoeoegrau-gfaschtnd', 'Des Haus hauma in Oidroosa gschdrichn, und de Fensta in Höögrau gfaschtnd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Haus haben wir in Altrosa gestrichen und die Fenster in hellgrau gefatscht!', '[{"kategorie": "wörtlich", "text": "\"Das Haus wurde in Altrosa gestrichen, und die Fenster wurden in hellgrau gefascht!\"  2. Das Gebäude wurde altrosa verputzt, die Fenster mit hellgrauen Putzbordüren gerahmt!  3. Wir haben das Haus rosa gestrichen und dann graue Umrandungen um die Fenster gezogen – schaut echt gut aus!"}]'::jsonb, ''),
  ('da-greessde-faulenza-bei-uns-im-haus-is-da-hund-dea-schloofd-18-schdund-aum-toog', 'Da greessde Faulenza bei uns im Haus is da Hund - dea schloofd 18 Schdund aum Toog!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der größte Faulenzer bei uns im Haus ist der Hund - der schläft 18 Stunden am Tag!', '[{"kategorie": "wörtlich", "text": "\"Der größte [[Owezaara]] bei uns im Haus ist der Hund - der schäft 18 Stunden am Tag!\"  2. Bei uns ist der Hund der größte Couchpotato - schläft 18 Stunden am Tag!  3. Der faulste Kerl bei uns im Haus ist der Hund - der schläft 18 Stunden am Tag!"}]'::jsonb, ''),
  ('oone-faulenza-untan-weissn-blaadl-papia-daedad-i-heit-no-schiif-schreibm', 'Oone Faulenza untan weissn Blaadl Papia dädad I heit no schiif schreibm!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ohne Faulenzer unter einem weißen Blatt Papier würde ich heute noch schief schreiben!', '[{"kategorie": "wörtlich", "text": "\"Ohne einen Linienspiegel unter dem weißen Blatt Papier würde ich heute noch schief schreiben!\"  2. Ohne Schreibhilfe unter dem leeren Blatt würde ich heute noch schiefe Zeilen schreiben!  3. Ohne das Linienblatt unterm Papier wär meine Schrift bis heute nicht gerade!"}]'::jsonb, ''),
  ('im-feeba-is-in-wiin-meistns-schiach-lauta-gatsch-und-neewae', 'Im Feeba is in Wiin meistns schiach - lauta Gatsch und Neewä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Im Feber ist es in Wien meist schirch - lauter Gatsch und Nebel!', '[{"kategorie": "wörtlich", "text": "\"Wien im Feber ist meist trist – überall Schneematsch und kaltgrauer Nebel!\"  2. Im Februar zeigt sich Wien meist von seiner grausten Seite – nur Matsch und dichter Nebel!  3. Wer Wien im Feber mag, hat auch eine Vorliebe für kalte, nasse Socken!"}]'::jsonb, ''),
  ('ois-fechta-muassd-ned-nua-schnoeoe-sei-sondan-aa-strategisch-denkn', 'Ois Fechta muassd ned nua schnöö sei, sondan aa strategisch denkn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Als Fechter musst du nicht nur schnell sein, sondern auch strategisch denken!', '[{"kategorie": "wörtlich", "text": "\"Als Fechter musst du nicht nur schnell sein, sondern stets auch eine Strategie im Kopf haben!\"  2. Ein Fechter braucht nicht nur Schnelligkeit, sondern auch taktisches Geschick!  3. Ein guter Fechter kombiniert Geschwindigkeit mit strategischem Denken!"}]'::jsonb, ''),
  ('zua-oidn-wiina-kaisaschdodt-haum-fechta-genauso-dazuaghead-wia-fiaka-und-zeitungstraeaega', 'Zua oidn Wiina Kaisaschdodt haum Fechta genauso dazuaghead wia Fiaka und Zeitungsträäga!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Zur alten Wiener Kaiserstadt haben Fechter genauso dazugehört wie Fiaker und Zeitungsträger!', '[{"kategorie": "wörtlich", "text": "\"Zum historischen Stadtbild der Wiener Kaiserstadt gehörten einst Straßenbettler genauso wie Fiaker und Zeitungsträger!\"  2. Bettler waren im Wien der Kaiserzeit genauso verbreitet wie Fiaker oder Zeitungsverkäufer!  3. Zur Kaiserzeit zogen nicht nur Pferdekutschen, sondern auch Bettler und Zeitungsträger durch die Gassen Wiens!"}]'::jsonb, ''),
  ('i-hob-feedan-vua-da-haeae', 'I hob Feedan vua da Hää!', '', '', '', 'Wiener Gaunersprache', 'Ich habe Federn vor der Höh!', '[{"kategorie": "wörtlich", "text": "\"Ich hab Schiss vor den Bullen!\"  2. Ich hab Angst vor der Polizei!  3. Ich hab Muffensausen vor der [[Kieberei]]!"}]'::jsonb, 'de Feedan haum'),
  ('pass-auf-oida-sunst-foar-i-da-min-feidl-iwas-gsichd', 'Pass auf, Oida, sunst foar I da min Feidl iwas Gsichd!', '', '', '', 'Wiener Gaunersprache', 'Pass auf, Alter, sonst fahr ich dir mit''m Feitel übers Gesicht!', '[{"kategorie": "wörtlich", "text": "\"Pass auf, Alter, sonst kriegst eine Signatur mit''n Messer auf die Stirn!\"  2. Gib Acht, Mann, sonst schnitz ich dir mit meinem Klappmesser eine Signatur quer übers Gesicht!  3. Noch ein Mucks, Alter, und ich rasier dir mit''m Feitel das Grinsen aus deinem Gesicht!"}]'::jsonb, ''),
  ('seit-de-uschi-min-aubrenndn-geed-reeds-von-nix-aussa-sein-feidl', 'Seit de Uschi min Aubrenndn geed, reeds von nix aussa sein Feidl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit die Uschi mit dem Angebrannten geht, redet sie von nichts außer seinem Feitel!', '[{"kategorie": "wörtlich", "text": "\"Seit die Uschi mit dem Schwarzafrikaner geht, redet sie von nichts außer seinem Schneidwerkzeug!\"  2. Seit die Uschi mit dem Afrikaner geht, schwärmt sie nur noch von seinem Gerät!  3. Seit die Uschi mit dem Sambatänzer geht, redet sie von nichts anderem mehr als seinem Schniedel!"}]'::jsonb, ''),
  ('da-opa-hockd-in-gaunz-toog-im-goatn-und-feidld-aun-sein-schbaziaschdock', 'Da Opa hockd in gaunz Toog im Goatn und feidld aun sein Schbaziaschdock!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Opa hockt den ganzen Tag im Garten und feitelt an seinem Spazierstock!', '[{"kategorie": "wörtlich", "text": "\"Opa sitzt den ganzen Tag im Garten und schnitzt an seinem Spazierstock rum!\"  2. Opa sitzt den ganzen Tag draußen im Garten und bearbeitet seinen Spazierstock mit dem Taschenmesser!  3. Der Alte sitzt den ganzen Tag draußen und schabt stundenlang an seinem Spazierstock!"}]'::jsonb, ''),
  ('do-mechd-i-feidl-haassn', 'Do mechd I Feidl haassn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da möchte ich Veitl heißen!', '[{"kategorie": "wörtlich", "text": "\"Da möchte ich Veitel heißen!\"  2. (scherzhaft für): Da will ich doch Einstein heißen!  3. Wenn das stimmt, bin ich der Kaiser von China!  4. Wenn das wahr ist, fress ich einen Besen!  5. Bei allen Heiligen, das glaub ich nie und nimmer!  6. (Deutschland): \"Da wird doch der Hund in der Pfanne verrückt!\""}]'::jsonb, ''),
  ('waunnsd-beim-hoibseidanan-an-bleedn-schmaeae-schiabsd-is-da-toschnfeidl-aa-schoo-aufkloppd', 'Waunnsd beim Hoibseidanan an bleedn Schmää schiabsd, is da Toschnfeidl aa schoo aufkloppd!', '', '', '', 'Wiener Gaunersprache', 'Wenn du beim Halbseidenen einen blöden Schmäh schiebst, ist der Taschenfeitel auch schon aufgeklappt!', '[{"kategorie": "wörtlich", "text": "\"Wenn du bei diesem Zuhältertypen einen blöden Schmäh machst, klappt auch schon sein Taschenfeitel auf!\"  2. Wennst bei diesem Unterweltler einen Blödsinn redst, hat er das Klappmesser schneller draußen als du Luft holen kannst!  3. Ein falsches Wort bei diesem Zuhälter, und sein Taschenfeitel macht schon Klick!"}]'::jsonb, ''),
  ('host-den-faeschak-gseeng-gschniigld-wia-waunna-zum-oopanboi-gingad', 'Host den Fäschak gseeng? Gschniigld, wia waunna zum Oopanboi gingad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hast du den Feschak gesehen? Geschniegelt, wie wenn er zum Opernball ginge!', '[{"kategorie": "wörtlich", "text": "\"Hast du den Schönling gesehen? Aufgestylt, als würde er zum Opernball gehen!\"  2. \"Hast du den Schickimicki gesehen? Aufgebrezelt, wie wenn er zum Opernball ginge!\"  3. Hast du den Beau gesehen? Rausgeputzt von Kopf bis Fuß - fast schon zu schön für die Straße!"}]'::jsonb, ''),
  ('fettn2', 'Fettn2', 'die', '', '', 'Grundwortschatz Wienerisch', 'Fetten', '[{"kategorie": "wörtlich", "text": "\"Seitwärtsdrall\" (vom französischen \"effet\"=\"Drall\")"}, {"kategorie": "allg.", "text": "Drall, Spin, Schnitt, Drehung, Rotation (Billardkugel, Fußball, etc."}, {"kategorie": "scherzhaft für", "text": "Rausch, Trunkenheit, [[Fetzen]], [[Siada]], [[Öl]]"}]'::jsonb, 'in Boin mit ana Fettn audraan'),
  ('fettn1', 'Fettn1', 'die', '', '', 'Grundwortschatz Wienerisch', 'Fetten', '[{"kategorie": "wörtlich", "text": "\"Fetten\" (vom mittelhochdeutschen \"vet\"=\"Fett\")"}, {"kategorie": "med.", "text": "Fett, Lipid, Triglyzerid (einer der Grundnährstoffe höherer Lebewesen), Omega-Fett (gesättigte/ungesättigte Fettsäure)"}, {"kategorie": "", "text": "Nahrungsfett, Speisefett, Bratfett"}, {"kategorie": "", "text": "Fettmasse, Fettgewebe, Fettpolster"}, {"kategorie": "", "text": "Körperfülle, Dickleibigkeit, Korpulenz, Beleibtheit"}]'::jsonb, 'Fettn liifad Enagii – sogoa mea ois Zucka!'),
  ('fettn-liifad-enagii-sogoa-mea-ois-zucka', 'Fettn liifad Enagii – sogoa mea ois Zucka!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Fett liefert Energie - sogar mehr als Zucker!', '[{"kategorie": "wörtlich", "text": "\"Fett ist ein effizienter Energiespeicher – energiereicher als Zucker!\"  2. Fette sind die energiereichsten Nährstoffe – sie liefern mehr Energie als Zucker oder Eiweiß!  3. Ein Gramm Fett enthält etwa 9 Kilokalorien – mehr als Zucker mit rund 4!"}]'::jsonb, ''),
  ('oone-fettn-schmeckd-hoid-nix-froog-moi-de-omi', 'Oone Fettn schmeckd hoid nix - froog moi de Omi!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ohne Fett schmeckt halt nix – frag mal die Omi!', '[{"kategorie": "wörtlich", "text": "\"Ohne Fett fehlt einfach der Geschmack – frag nach bei Oma!\"  2. Fett bringt das Aroma – so einfach ist das, sagt die Oma!  3. Ohne Fett fehlt die Seele im Essen – das wusste schon unsere Oma!"}]'::jsonb, ''),
  ('dem-kwueued-beim-hemd-de-fettn-ausse', 'Dem kwüüd beim Hemd de Fettn ausse!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem quillt beim Hemd die Fetten raus!', '[{"kategorie": "wörtlich", "text": "\"Dem quillt beim Hemd das Fettgewebe raus!\"  2. Der platzt aus allen Nähten!  3. Der passt kaum noch in sein Hemd!"}]'::jsonb, ''),
  ('trotz-seina-fettn-beweegda-si-echt-geschmeidig', 'Trotz seina Fettn beweegda si echt geschmeidig!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Trotz seiner Fetten bewegt er sich echt geschmeidig!', '[{"kategorie": "wörtlich", "text": "\"Trotz seiner Körperfülle bewegt er sich erstaunlich leichtfüßig!\"  2. Trotz seines Körperumfangs sind seine Bewegungen richtig elegant!  3. Trotz seiner Fetten ist er flink wie ein Wiesel!"}]'::jsonb, ''),
  ('in-boin-a-fettn-geem', 'in Boin a Fettn geem', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'dem Ball eine Fetten geben', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"dem Ball viel Drall geben\""}, {"kategorie": "", "text": "den Ball mit viel Effet schießen"}, {"kategorie": "", "text": "den Ball mit ordentlich Spin spielen"}, {"kategorie": "", "text": "dem Ball viel Schnitt geben"}]'::jsonb, 'Dea gibd in Boin sovüü Fettn, dassa fost an Boong zruck mochd!'),
  ('dea-gibd-in-boin-sovueue-fettn-dassa-fost-an-boong-zruck-mochd', 'Dea gibd in Boin sovüü Fettn, dassa fost an Boong zruck mochd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der gibt dem Ball so viel Fetten, dass er fast einen Bogen zurück macht!', '[{"kategorie": "wörtlich", "text": "\"Der gibt dem Ball so viel Schnitt, dass er fast einen Bogen zurück macht!\"  2. Der dreht den Ball mit so viel Spin rein, dass er fast wieder zurückkommt!  3. Bei ihm hat der Ball so viel Effet drauf, dass er fast wie ein Bumerang zurückfliegt!"}]'::jsonb, 'in Boin a Fettn geem'),
  ('in-boin-a-fettn-mitgeem', 'in Boin a Fettn mitgeem', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'dem Ball eine Fetten mitgeben', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"dem Ball sehr viel Drall mitgeben\""}, {"kategorie": "", "text": "den Ball mit viel Effet schießen"}, {"kategorie": "", "text": "den Ball mit ordentlich Spin spielen"}]'::jsonb, 'Dea hod in Boin a so a dreckige Fettn mitgeem, dass da Gooli nimma gwuussd hod, wo vuan und hint is!'),
  ('dea-hod-in-boin-a-so-a-dreckige-fettn-mitgeem-dass-da-gooli-nimma-gwuussd-hod-wo-vuan-und-hint-is', 'Dea hod in Boin a so a dreckige Fettn mitgeem, dass da Gooli nimma gwuussd hod, wo vuan und hint is!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der hat dem Ball eine derart dreckige Fetten mitgegeben, dass der Goalie nicht mehr gewusst hat, wo vorne und hinten ist!', '[{"kategorie": "wörtlich", "text": "\"Der hat dem Ball einen derart fiesen Schnitt mitgegeben, dass der Goalie nicht mehr gewusst hat, wo vorne und hinten ist!\"  2. Der Typ hat in den Schuss so viel unberechenbaren Effet reingelegt, dass der Torwart nur mehr Luftlöcher schlagen konnte!  3. Der hat die Kugel mit so viel bösem Spin geschossen, dass der Keeper dem Ball nur noch nachschauen konnte!"}]'::jsonb, 'in Boin a Fettn mitgeem'),
  ('in-boin-mit-ana-fettn-audraan', 'in Boin mit ana Fettn audraan', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'den Ball mit einer Fetten andrehen', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"dem Ball sehr viel Drall mitgeben\""}, {"kategorie": "", "text": "den Ball mit viel Effet schießen"}, {"kategorie": "", "text": "den Ball mit ordentlich Spin spielen"}, {"kategorie": "", "text": "dem Ball ordentlich viel Schnitt mitgeben"}]'::jsonb, ''),
  ('da-rechtsaussn-draad-in-boin-mid-so-ana-fettn-au-dass-da-schdueama-nua-mea-sei-bian-hihoidn-muass', 'Da Rechtsaussn draad in Boin mid so ana Fettn au, dass da Schdüama nua mea sei Bian hihoidn muass!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Rechtsaußen dreht den Ball mit so einer Fetten an, dass der Stürmer nur mehr seine Birne hinhalten muss!', '[{"kategorie": "wörtlich", "text": "\"Der Rechtsaußen dreht den Ball mit so viel Schnitt an, dass der Stürmer nur mehr seinen Kopf hinhalten muss!\"  2. Der Flügelspieler schlägt den Ball mit so einem perfektem Effet in die Mitte, dass der Stürmer nur noch einnicken muss!  3. Der Ball kommt vom Rechtsaußen mit so viel Drall in den Strafraum, dass der Stürmer nur noch seine Rübe hinhalten muss!"}]'::jsonb, ''),
  ('de-tapeedn-ghean-gfetzd', 'De Tapeedn ghean gfetzd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Tapeten gehören gefetzt!', '[{"kategorie": "wörtlich", "text": "\"Die Tapeten gehören abgerissen!\"  2. Die Tapeten müssen runter!  3. Die Tapeten sind zu entfernen - und zwar komplett!"}]'::jsonb, ''),
  ('tua-ned-so-fetzn-des-kaunn-jo-kaana-leesn', 'Tua ned so fetzn - des kaunn jo kaana leesn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Tu nicht so fetzen - das kann ja keiner lesen!', '[{"kategorie": "wörtlich", "text": "\"Schmier nicht so - das kann ja keiner lesen!\"  2. Schreib bitte leserlich - das ist ja kaum zu entziffern!  3. Was soll das Geschmiere - kannst du nicht leserlicher schreiben?"}]'::jsonb, ''),
  ('mit-dem-fetzinga-dischkutian-is-wiaran-sock-flee-dressian', 'Mit dem Fetzinga dischkutian is wiaran Sock Flee dressian!', '', '', '', 'Wiener Gaunersprache', 'Mit diesem Fetzinger zu diskutieren ist wie einen Sack Flöhe dressieren!', '[{"kategorie": "wörtlich", "text": "\"Mit diesem Streithammel zu diskutieren ist wie einen Sack Flöhe dressieren!\"  2. Mit diesem Krawallbruder zu diskutieren, bringt nichts - der hört nur sich selbst!  3. Jede Diskussion mit diesem [[Streithansel]] ist sinnlos - man redet bei ihm wie gegen die Wand!"}]'::jsonb, ''),
  ('schau-da-den-fetzinga-min-goidkeedal-au-tuad-auf-schweareicha-und-woond-no-bei-da-mutti-im-koella', 'Schau da den Fetzinga min Goidkeedal au - tuad auf Schweareicha und woond no bei da Mutti im Kölla!', '', '', '', 'Wiener Gaunersprache', 'Schau dir den Fetzinger mit dem Goldketterl an - tut auf Schwerreicher und wohnt noch bei der Mutti im Keller!', '[{"kategorie": "wörtlich", "text": "\"Schau dir den Angeber mit dem Goldkettchen an - tut auf Schwerreicher und wohnt noch bei Mutti im Keller!\"  2. Sieh dir den Lackaffen mit Goldkettchen an - tut einen auf großer Macker und schläft noch bei Mutti unterm Hochbett!  3. Gib dir diesen Goldkettchen-Heini - wirft mit Geld um sich, dabei wohnt er noch bei Mutti zu Hause!"}]'::jsonb, ''),
  ('de-zwa-fetzn-si-scho-wiida', 'De zwa fetzn si scho wiida!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Die beiden fetzen sich schon wieder!', '[{"kategorie": "wörtlich", "text": "\"Die beiden streiten schon wieder!\"  2. Die beiden liegen schon wieder im Clinch miteinander!  3. Die beiden liegen einander schon wieder in den Haaren!"}]'::jsonb, ''),
  ('dea-fetzd-min-ua-karacho-um-de-eckn', 'Dea fetzd min ua Karacho um de Eckn!', '', '', '', 'Wiener Mechaniker-Slang', 'Der fetzt mit einem Ur-Karacho um die Ecke!', '[{"kategorie": "wörtlich", "text": "\"Der schießt in einem Mordstempo um die Ecke!\"  2. Der brettert mit einem Affenzahn um die Ecke!  3. Der braust in Höchstgeschwindigkeit um die Ecke!"}]'::jsonb, ''),
  ('fetzn-kaunnst-waunnsd-de-hockn-kriagst', 'Fetzn kaunnst, waunnsd de Hockn kriagst!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Fetzen kannst du, wenn du die Hacken kriegst!', '[{"kategorie": "wörtlich", "text": "\"Protzen kannst du, wenn du den Job bekommst!\"  2. Große Töne spucken kannst du, wenn du die Stelle kriegst!  3. Auf den Putz hauen kannst du, sobald du den Job in der Tasche hast!"}]'::jsonb, ''),
  ('de-blonde-im-roodn-fetzal-is-ned-zum-iwaseeng-do-is-mea-luft-ois-schdoff', 'De Blonde im roodn Fetzal is ned zum Iwaseeng - do is mea Luft ois Schdoff!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Blonde im roten Fetzerl ist nicht zu übersehen - da ist mehr Luft als Stoff!', '[{"kategorie": "wörtlich", "text": "\"Die Blonde im roten String-Tanga ist nicht zu übersehen - da ist mehr Luft als Stoff!\"  2. Der rote Tanga von dieser Blondine hat weniger Stoff als ein Teebeutel!  3. Die Blonde im roten Fetzerl ist nicht zu übersehen - weniger Stoff geht nämlich nimmer!"}]'::jsonb, ''),
  ('i-daschlog-di-mid-an-nossn-fetzn', 'I daschlog di mid an nossn Fetzn!', '', '', '', 'Wiener Gaunersprache', 'Ich erschlage dich mit einem nassen Fetzen!', '[{"kategorie": "wörtlich", "text": "\"Ich schlage dich mit einem nassen Fetzen tot!\"  2. Ich schlag dir einen nassen Fetzen um die Ohren, dass dir drei Tage lang das Regenwasser aus dem Schädel rinnt!  3. Ich schlag dir mit ''nem nassen Fetzen das Hirn aus dem Schädel!"}]'::jsonb, ''),
  ('reib-ma-an-fetzn', 'Reib ma an Fetzn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Reibe mir einen Fetzen!', '[{"kategorie": "wörtlich, scherzhaft für", "text": "\"Leih mir 500 Euro!\"  2. Gib mir 500 Euro auf Pump!  3. Kannst du mir mit einem 500-Euro-Schein aushelfen?"}]'::jsonb, ''),
  ('mia-haums-in-fetzn-oognumma', 'Mia haums in Fetzn oognumma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mir haben sie den Fetzen abgenommen!', '[{"kategorie": "wörtlich", "text": "\"Mir haben sie den Führerschein abgenommen!\"  2. Die haben mir den Lappen einkassiert!  3. Sie haben mir den [[Deckel]] garniert!  4. Sie haben mir den Schein gestanzt!  5. Sie haben mir den [[Hadern]] gestanzt!"}]'::jsonb, '')
